		JsonMapper normalBinder = JsonMapper.defaultMapper();
		TestBean bean = new TestBean("A");

		Map<String, Object> normalExpected = new HashMap<>();
		normalExpected.put("name", "A");
		normalExpected.put("defaultValue", "hello");
		normalExpected.put("nullValue", null);
		normalExpected.put("emptyValue", new ArrayList<>());
		assertThat((Map<?, ?>) normalBinder.fromJson(normalBinder.toJson(bean), Map.class))
				.isEqualTo(normalExpected);

		// 不打印nullValue属性
		JsonMapper nonNullMapper = JsonMapper.nonNullMapper();
		Map<String, Object> nonNullExpected = new HashMap<>();
		nonNullExpected.put("name", "A");
		nonNullExpected.put("defaultValue", "hello");
		nonNullExpected.put("emptyValue", new ArrayList<>());
		assertThat((Map<?, ?>) nonNullMapper.fromJson(nonNullMapper.toJson(bean), Map.class))
				.isEqualTo(nonNullExpected);

		// 不打印nullValue与empty的属性
		JsonMapper nonEmptyMapper = JsonMapper.nonEmptyMapper();
		Map<String, Object> nonEmptyExpected = new HashMap<>();
		nonEmptyExpected.put("name", "A");
		nonEmptyExpected.put("defaultValue", "hello");
		assertThat((Map<?, ?>) nonEmptyMapper.fromJson(nonEmptyMapper.toJson(bean), Map.class))
				.isEqualTo(nonEmptyExpected);

