                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray=<null>," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";
        final String actual = toString(wa);

        final String[] expLines = exp.split(java.util.regex.Pattern.quote(BR), -1);
        final String[] actualLines = actual.split(java.util.regex.Pattern.quote(BR), -1);

        assertEquals(expLines.length, actualLines.length);
        assertEquals(expLines[0], actualLines[0]);
        assertEquals(expLines[expLines.length - 1], actualLines[actualLines.length - 1]);

        final List<String> expFields = new ArrayList<>();
        final List<String> actualFields = new ArrayList<>();

        for (int i = 1; i < expLines.length - 1; i++) {
            final String line = expLines[i];
            expFields.add(line.endsWith(",") ? line.substring(0, line.length() - 1) : line);
        }

        for (int i = 1; i < actualLines.length - 1; i++) {
            final String line = actualLines[i];
            if (i == actualLines.length - 2) {
                assertEquals(false, line.endsWith(","));
            } else {
                assertEquals(true, line.endsWith(","));
            }
            actualFields.add(line.endsWith(",") ? line.substring(0, line.length() - 1) : line);
        }

        java.util.Collections.sort(expFields);
        java.util.Collections.sort(actualFields);
        assertEquals(expFields, actualFields);
    }
