    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        Assert.assertTrue(sql.startsWith("SELECT "));
        int fromIndex = sql.indexOf("  FROM user ");
        Assert.assertTrue(fromIndex > "SELECT ".length());
        String selectColumns = sql.substring("SELECT ".length(), fromIndex);
        String[] columns = selectColumns.split(",");
        Assert.assertEquals(4, columns.length);
        java.util.Set<String> actualColumns = new java.util.HashSet<String>();
        for (String column : columns) {
            actualColumns.add(column.trim());
        }
        java.util.Set<String> expectedColumns = new java.util.HashSet<String>();
        expectedColumns.add("id");
        expectedColumns.add("user_name");
        expectedColumns.add("address");
        expectedColumns.add("state");
        Assert.assertEquals(expectedColumns, actualColumns);

        Assert.assertTrue(sql.contains("<where>"));
        Assert.assertTrue(sql.contains("</where>"));
        Assert.assertTrue(sql.contains("<if test=\"id != null\"> AND id = #{id}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"userName != null\"> AND user_name = #{userName}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"state != null\"> AND state = #{state}</if>"));
        Assert.assertEquals(4, sql.split("<if test=", -1).length - 1);

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals(4, resultMappings.size());

        ResultMapping idMapping = null;
        ResultMapping userNameMapping = null;
        ResultMapping addressMapping = null;
        ResultMapping stateMapping = null;
        for (ResultMapping mapping : resultMappings) {
            if ("id".equals(mapping.getProperty())) {
                idMapping = mapping;
            } else if ("userName".equals(mapping.getProperty())) {
                userNameMapping = mapping;
            } else if ("address".equals(mapping.getProperty())) {
                addressMapping = mapping;
            } else if ("state".equals(mapping.getProperty())) {
                stateMapping = mapping;
            }
        }

        Assert.assertNotNull(idMapping);
        Assert.assertNotNull(userNameMapping);
        Assert.assertNotNull(addressMapping);
        Assert.assertNotNull(stateMapping);

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
