    @Test
    public void testPerson() {
        final Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        final String pBaseStr = p.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p));
        final String pJobStr  = p.job.getClass().getName() + "@" + Integer.toHexString(System.identityHashCode(p.job));

        final String actual = new ReflectionToStringBuilder(p, new RecursiveToStringStyle()).toString();

        final String[] expectedFields = {
            "name=John Doe",
            "age=33",
            "smoker=false",
            "job=" + pJobStr + "[title=Manager]"
        };
        Arrays.sort(expectedFields);
        final String expectedCanonical = pBaseStr + "[" + String.join(",", expectedFields) + "]";

        final int openBracket = actual.indexOf('[');
        final String actualPrefix = actual.substring(0, openBracket);
        final String actualBody = actual.substring(openBracket + 1, actual.length() - 1);
        final String[] actualFields = actualBody.split(",", -1);
        Arrays.sort(actualFields);
        final String actualCanonical = actualPrefix + "[" + String.join(",", actualFields) + "]";

        assertEquals(expectedCanonical, actualCanonical);
    }
