                return s;
            }
            final String body = s.substring(open + 1, close);
            final String[] entries = body.isEmpty() ? new String[0] : body.split(",", -1);
            java.util.Arrays.sort(entries);
            return s.substring(0, open + 1) + String.join(",", entries) + s.substring(close);
