    @Test
    public void handlesMethodNotAllowedWithHeaders() throws Exception {
        final Throwable thrown = catchThrowable(() -> target("/exception/json-mapping-exception")
            .request(MediaType.APPLICATION_JSON)
            .post(Entity.json("A"), String.class));
        assertThat(thrown).isInstanceOf(WebApplicationException.class);
        final Response resp = ((WebApplicationException) thrown).getResponse();
        assertThat(resp.getStatus()).isEqualTo(405);

        final List<String> allowedMethods = resp.getHeaders().getOrDefault("Allow", Collections.emptyList())
            .stream()
            .flatMap(value -> Arrays.stream(value.toString().split(",")))
            .map(String::trim)
            .filter(method -> !method.isEmpty())
            .sorted()
            .collect(Collectors.toList());
        assertThat(allowedMethods).containsExactly("GET", "OPTIONS");

        final ObjectMapper mapper = new ObjectMapper();
        assertThat(mapper.readTree(resp.readEntity(String.class)))
            .isEqualTo(mapper.readTree("{\"code\":405,\"message\":\"HTTP 405 Method Not Allowed\"}"));
    }
