    String notificationsJson = URLDecoder.decode(encodedNotifications, "UTF-8");
    JsonArray notifications = new JsonParser().parse(notificationsJson).getAsJsonArray();
    assertEquals(2, notifications.size());

    Set<String> actualNotifications = new HashSet<>();
    for (JsonElement element : notifications) {
      JsonObject notification = element.getAsJsonObject();
      assertEquals(2, notification.entrySet().size());
      assertTrue(notification.has("namespaceName"));
      assertTrue(notification.has("notificationId"));
      String namespaceName = notification.get("namespaceName").getAsString();
      long notificationId = notification.get("notificationId").getAsLong();
      actualNotifications.add(namespaceName + "\u0000" + notificationId);
    }

    Set<String> expectedNotifications = new HashSet<>();
    for (Map.Entry<String, Long> entry : notificationsMap.entrySet()) {
      expectedNotifications.add(entry.getKey() + "\u0000" + entry.getValue());
    }
    assertEquals(expectedNotifications, actualNotifications);
  }
