  @Test public void userSuppliedJaxbContext() throws Exception {
    JAXBContext context = JAXBContext.newInstance(Contact.class);
    JaxbConverterFactory factory = JaxbConverterFactory.create(context);
    Retrofit retrofit = new Retrofit.Builder()
        .baseUrl(server.url("/"))
        .addConverterFactory(factory)
        .build();
    service = retrofit.create(Service.class);

    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");
    String actualXml = request.getBody().readUtf8();
    assertThat(actualXml).startsWith("<?xml version=\"1.0\" ?>");

    class XmlCanonicalizer {
      String canonicalize(org.w3c.dom.Node node) {
        StringBuilder result = new StringBuilder();
        appendNode(node, result);
        return result.toString();
      }

      private void appendNode(org.w3c.dom.Node node, StringBuilder result) {
        switch (node.getNodeType()) {
          case org.w3c.dom.Node.DOCUMENT_NODE:
            appendNode(((org.w3c.dom.Document) node).getDocumentElement(), result);
            break;
          case org.w3c.dom.Node.ELEMENT_NODE:
            org.w3c.dom.Element element = (org.w3c.dom.Element) node;
            result.append('<').append(element.getTagName());
            org.w3c.dom.NamedNodeMap attributes = element.getAttributes();
            java.util.TreeMap<String, String> sortedAttributes = new java.util.TreeMap<>();
            for (int i = 0; i < attributes.getLength(); i++) {
              org.w3c.dom.Node attribute = attributes.item(i);
              sortedAttributes.put(attribute.getNodeName(), attribute.getNodeValue());
            }
            for (java.util.Map.Entry<String, String> attribute : sortedAttributes.entrySet()) {
              result.append(' ').append(attribute.getKey()).append("=\"");
              escape(attribute.getValue(), result);
              result.append('"');
            }
            result.append('>');
            java.util.List<String> children = new java.util.ArrayList<>();
            org.w3c.dom.NodeList childNodes = element.getChildNodes();
            for (int i = 0; i < childNodes.getLength(); i++) {
              StringBuilder child = new StringBuilder();
              appendNode(childNodes.item(i), child);
              children.add(child.toString());
            }
            java.util.Collections.sort(children);
            for (String child : children) {
              result.append(child);
            }
            result.append("</").append(element.getTagName()).append('>');
            break;
          case org.w3c.dom.Node.TEXT_NODE:
          case org.w3c.dom.Node.CDATA_SECTION_NODE:
            result.append("#text:");
            escape(node.getNodeValue(), result);
            result.append(';');
            break;
          case org.w3c.dom.Node.COMMENT_NODE:
            result.append("#comment:");
            escape(node.getNodeValue(), result);
            result.append(';');
            break;
          case org.w3c.dom.Node.PROCESSING_INSTRUCTION_NODE:
            result.append("#pi:").append(node.getNodeName()).append(':');
            escape(node.getNodeValue(), result);
            result.append(';');
            break;
          default:
            break;
        }
      }

      private void escape(String value, StringBuilder result) {
        if (value == null) {
          return;
        }
        for (int i = 0; i < value.length(); i++) {
          char c = value.charAt(i);
          switch (c) {
            case '&':
              result.append("&amp;");
              break;
            case '<':
              result.append("&lt;");
              break;
            case '>':
              result.append("&gt;");
              break;
            case '"':
              result.append("&quot;");
              break;
            default:
              result.append(c);
          }
        }
      }
    }

    javax.xml.parsers.DocumentBuilderFactory documentBuilderFactory =
        javax.xml.parsers.DocumentBuilderFactory.newInstance();
    org.w3c.dom.Document expectedDocument = documentBuilderFactory.newDocumentBuilder()
        .parse(new org.xml.sax.InputSource(new java.io.StringReader(SAMPLE_CONTACT_XML)));
    org.w3c.dom.Document actualDocument = documentBuilderFactory.newDocumentBuilder()
        .parse(new org.xml.sax.InputSource(new java.io.StringReader(actualXml)));

    XmlCanonicalizer canonicalizer = new XmlCanonicalizer();
    assertThat(canonicalizer.canonicalize(actualDocument))
        .isEqualTo(canonicalizer.canonicalize(expectedDocument));
  }
