  @Test public void xmlRequestBody() throws Exception {
    server.enqueue(new MockResponse());

    Call<Void> call = service.postXml(SAMPLE_CONTACT);
    call.execute();

    RecordedRequest request = server.takeRequest();
    assertThat(request.getHeader("Content-Type")).isEqualTo("application/xml; charset=utf-8");

    String actualXml = request.getBody().readUtf8();
    assertThat(actualXml).startsWith("<?xml version=\"1.0\" ?>");

    class XmlNormalizer {
      String normalize(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        Document document = factory.newDocumentBuilder()
            .parse(new InputSource(new StringReader(xml)));
        return normalize(document.getDocumentElement());
      }

      String normalize(Element element) {
        StringBuilder result = new StringBuilder();
        result.append('<').append(element.getTagName());

        NamedNodeMap attributes = element.getAttributes();
        TreeMap<String, String> sortedAttributes = new TreeMap<>();
        for (int i = 0; i < attributes.getLength(); i++) {
          Node attribute = attributes.item(i);
          sortedAttributes.put(attribute.getNodeName(), attribute.getNodeValue());
        }
        for (Map.Entry<String, String> attribute : sortedAttributes.entrySet()) {
          result.append(' ')
              .append(attribute.getKey())
              .append("=\"")
              .append(attribute.getValue())
              .append('"');
        }
        result.append('>');

        List<Element> childElements = new ArrayList<>();
        StringBuilder text = new StringBuilder();
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
          Node child = children.item(i);
          if (child.getNodeType() == Node.ELEMENT_NODE) {
            childElements.add((Element) child);
          } else if (child.getNodeType() == Node.TEXT_NODE
              || child.getNodeType() == Node.CDATA_SECTION_NODE) {
            text.append(child.getNodeValue());
          }
        }

        Collections.sort(childElements, new Comparator<Element>() {
          @Override public int compare(Element left, Element right) {
            return left.getTagName().compareTo(right.getTagName());
          }
        });

        if (childElements.isEmpty()) {
          result.append(text);
        } else {
          for (Element childElement : childElements) {
            result.append(normalize(childElement));
          }
          if (text.toString().trim().length() != 0) {
            result.append(text);
          }
        }

        result.append("</").append(element.getTagName()).append('>');
        return result.toString();
      }
    }

    XmlNormalizer normalizer = new XmlNormalizer();
    assertThat(normalizer.normalize(actualXml))
        .isEqualTo(normalizer.normalize(SAMPLE_CONTACT_XML));
  }
