    @Test
    public void noArray() {
        final WithArrays wa = new WithArrays();
        final String actual = toString(wa);

        final String prefix = getClassPrefix(wa) + "[" + BR;
        final String suffix = BR + "]";
        assertTrue(actual.startsWith(prefix), actual);
        assertTrue(actual.endsWith(suffix), actual);

        final String body = actual.substring(prefix.length(), actual.length() - suffix.length());
        final String[] lines = body.split(BR);
        final List<String> actualLines = new ArrayList<>();
        for (int i = 0; i < lines.length; i++) {
            final String line = lines[i];
            if (i < lines.length - 1) {
                assertTrue(line.endsWith(","), actual);
                actualLines.add(line.substring(0, line.length() - 1));
            } else {
                assertTrue(!line.endsWith(","), actual);
                actualLines.add(line);
            }
        }

        final List<String> expectedLines = new ArrayList<>();
        expectedLines.add("  boolArray=<null>");
        expectedLines.add("  charArray=<null>");
        expectedLines.add("  intArray=<null>");
        expectedLines.add("  doubleArray=<null>");
        expectedLines.add("  longArray=<null>");
        expectedLines.add("  stringArray=<null>");

        expectedLines.sort(null);
        actualLines.sort(null);
        assertEquals(expectedLines, actualLines, actual);
    }
