    public void test_dupType2() throws Exception {
        DianDianCart cart = new DianDianCart();
        cart.setId(1001);

        LinkedHashMap<String, HashMap<String, Object>> cartMap = new LinkedHashMap<String, HashMap<String, Object>>();

        HashMap<String, Object> obj = new HashMap<String, Object>();
        obj.put("id", 1001);
        obj.put(JSON.DEFAULT_TYPE_KEY, "com.alibaba.json.bvt.writeClassName.WriteDuplicateType$DianDianCart");
        cartMap.put("1001", obj);

        String text1 = JSON.toJSONString(cartMap, SerializerFeature.WriteClassName);
        String expected = "{\"@type\":\"java.util.LinkedHashMap\",\"1001\":{\"@type\":\"com.alibaba.json.bvt.writeClassName.WriteDuplicateType$DianDianCart\",\"id\":1001}}";

        Object expectedJson = JSON.parse(expected, Feature.DisableSpecialKeyDetect);
        Object actualJson = JSON.parse(text1, Feature.DisableSpecialKeyDetect);

        Assert.assertEquals(
                JSON.toJSONString(expectedJson, SerializerFeature.MapSortField),
                JSON.toJSONString(actualJson, SerializerFeature.MapSortField)
        );
    }
