8a217ce76d8d413c38a7bfd1.content:
//<fix start>
    public void test_list() throws Exception {
        Model model = new Model();
        Map tables = new LinkedHashMap();
        tables.put("1001", new ExtTable(1001));
        tables.put("1002", new Table());
        model.setTables(tables);

        String json = JSON.toJSONString(model);
        assertEquals("{\"tables\":{\"1001\":{\"@type\":\"com.alibaba.json.bvt.writeClassName.WriteClassNameTest_Map$ExtTable\",\"id\":1001},\"1002\":{}}}", json);

        JSONObject jsonObject = JSON.parseObject(json, Feature.IgnoreAutoType);
        assertNotNull(jsonObject);

        String actualJson = jsonObject.toJSONString();

        Map<String, Object> expected = new LinkedHashMap<String, Object>();
        Map<String, Object> expectedTables = new LinkedHashMap<String, Object>();
        Map<String, Object> expectedExtTable = new LinkedHashMap<String, Object>();
        expectedExtTable.put("id", 1001);
        expectedTables.put("1002", new LinkedHashMap<String, Object>());
        expectedTables.put("1001", expectedExtTable);
        expected.put("tables", expectedTables);

        JSONObject actual = JSON.parseObject(actualJson, Feature.IgnoreAutoType);
        assertNotNull(actual);
        assertEquals(expected, actual);
        assertEquals(expected.size(), actual.size());
        assertEquals(expectedTables.size(), actual.getJSONObject("tables").size());
        assertEquals(expectedExtTable, actual.getJSONObject("tables").getJSONObject("1001"));
        assertEquals(new LinkedHashMap<String, Object>(), actual.getJSONObject("tables").getJSONObject("1002"));

        Model model2 = JSON.parseObject(json, Model.class);
        assertEquals(ExtTable.class, model2.getTables().get("1001").getClass());
