    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final java.util.function.Function<String, String> canonicalize = value -> {
            final String[] lines = value.split(java.util.regex.Pattern.quote(BR), -1);
            final List<String> blocks = new ArrayList<>();
            StringBuilder current = null;
            for (int i = 1; i < lines.length - 1; i++) {
                final String line = lines[i];
                final boolean startsField = line.startsWith("  ") && !line.startsWith("   ") && line.indexOf('=') >= 0;
                if (startsField) {
                    if (current != null) {
                        blocks.add(current.toString());
                    }
                    current = new StringBuilder(line);
                } else {
                    if (current == null) {
                        throw new AssertionError("Unexpected line: " + line);
                    }
                    current.append(BR).append(line);
                }
            }
            if (current != null) {
                blocks.add(current.toString());
            }
            for (int i = 0; i < blocks.size(); i++) {
                final String block = blocks.get(i);
                if (block.endsWith(",")) {
                    blocks.set(i, block.substring(0, block.length() - 1));
                }
            }
            java.util.Collections.sort(blocks);
            final StringBuilder canonical = new StringBuilder(lines[0]);
            for (int i = 0; i < blocks.size(); i++) {
                canonical.append(BR).append(blocks.get(i));
                if (i < blocks.size() - 1) {
                    canonical.append(',');
                }
            }
            canonical.append(BR).append(lines[lines.length - 1]);
            return canonical.toString();
        };

        assertEquals(canonicalize.apply(exp), canonicalize.apply(toString(wa)));
    }
