//<fix start>
    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();
        final String expectedSql = "SELECT id,user_name,address,state  FROM user " +
                "<where>" +
                "<if test=\"id != null\"> AND id = #{id}</if>" +
                "<if test=\"userName != null\"> AND user_name = #{userName}</if>" +
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>" +
                "<if test=\"state != null\"> AND state = #{state}</if></where>";

        class SqlCanonicalizer {
            String canonicalize(String value) {
                int selectStart = value.indexOf("SELECT ");
                int fromMarker = value.indexOf("  FROM ");
                int whereMarker = value.indexOf(" <where>");
                int whereEnd = value.indexOf("</where>");
                Assert.assertEquals(0, selectStart);
                Assert.assertTrue(fromMarker > selectStart);
                Assert.assertTrue(whereMarker > fromMarker);
                Assert.assertTrue(whereEnd > whereMarker);
                Assert.assertTrue(value.endsWith("</where>"));

                String selectColumns = value.substring(selectStart + "SELECT ".length(), fromMarker);
                String[] columns = selectColumns.split(",", -1);
                java.util.Arrays.sort(columns);

                String table = value.substring(fromMarker + "  FROM ".length(), whereMarker);
                String whereContent = value.substring(whereMarker + " <where>".length(), whereEnd);

                java.util.regex.Pattern ifPattern = java.util.regex.Pattern.compile("<if\\b[^>]*>.*?</if>");
                java.util.regex.Matcher matcher = ifPattern.matcher(whereContent);
                StringBuilder originalIfs = new StringBuilder();
                java.util.List<String> ifClauses = new java.util.ArrayList<String>();
                while (matcher.find()) {
                    originalIfs.append(matcher.group());
                    ifClauses.add(matcher.group());
                }
                Assert.assertEquals(whereContent, originalIfs.toString());
                java.util.Collections.sort(ifClauses);

                StringBuilder canonical = new StringBuilder();
                canonical.append("SELECT ");
                for (int i = 0; i < columns.length; i++) {
                    if (i > 0) {
                        canonical.append(",");
                    }
                    canonical.append(columns[i]);
                }
                canonical.append("  FROM ").append(table).append(" <where>");
                for (String ifClause : ifClauses) {
                    canonical.append(ifClause);
                }
                canonical.append("</where>");
                return canonical.toString();
            }
        }

        SqlCanonicalizer canonicalizer = new SqlCanonicalizer();
        Assert.assertEquals(canonicalizer.canonicalize(expectedSql), canonicalizer.canonicalize(sql));

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals(4, resultMappings.size());
        java.util.Map<String, ResultMapping> mappingsByProperty = new java.util.HashMap<String, ResultMapping>();
        for (ResultMapping resultMapping : resultMappings) {
            mappingsByProperty.put(resultMapping.getProperty(), resultMapping);
        }
        Assert.assertEquals(
                new java.util.HashSet<String>(java.util.Arrays.asList("id", "userName", "address", "state")),
                mappingsByProperty.keySet());

        final ResultMapping idMapping = mappingsByProperty.get("id");
        final ResultMapping userNameMapping = mappingsByProperty.get("userName");
        final ResultMapping addressMapping = mappingsByProperty.get("address");
        final ResultMapping stateMapping = mappingsByProperty.get("state");

        Assert.assertNotNull(idMapping);
        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertNotNull(userNameMapping);
        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertNotNull(addressMapping);
        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertNotNull(stateMapping);
        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
    }
