public void test_dupType() throws Exception {
        DianDianCart cart = new DianDianCart();
        cart.setId(1001);

        LinkedHashMap<String, JSONObject> cartMap = new LinkedHashMap<String, JSONObject>();

        JSONObject obj = new JSONObject();
