    @Test
    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        final java.util.List<Integer> allThree = java.util.Arrays.asList(
                862547, 862583, 863879, 863951, 865247, 865283);
        final java.util.List<Integer> oneThree = java.util.Arrays.asList(23313, 23385);
        final java.util.List<Integer> oneTwo = java.util.Arrays.asList(23312, 23348);

        assertTrue(allThree.contains(HashCodeBuilder.reflectionHashCode(x)));

        assertTrue(allThree.contains(HashCodeBuilder.reflectionHashCode(x, (String[]) null)));
        assertTrue(allThree.contains(HashCodeBuilder.reflectionHashCode(x)));
        assertTrue(allThree.contains(HashCodeBuilder.reflectionHashCode(x, "xxx")));

        assertTrue(oneThree.contains(HashCodeBuilder.reflectionHashCode(x, "two")));
        assertTrue(oneTwo.contains(HashCodeBuilder.reflectionHashCode(x, "three")));

        assertEquals(17 * 37 + 1, HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(17, HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
