    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();
        final String baseString = this.toBaseString(instance1);

        final String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class);
        assertEquals(baseString, actual1.substring(0, baseString.length()));
        assertEquals('[', actual1.charAt(baseString.length()));
        assertEquals(']', actual1.charAt(actual1.length() - 1));
        final String[] fields1 = actual1.substring(baseString.length() + 1, actual1.length() - 1).split(",");
        assertEquals(2, fields1.length);
        assertEquals(
            new HashSet<>(Arrays.asList("staticString2=staticString2", "staticInt2=67890")),
            new HashSet<>(Arrays.asList(fields1)));

        final String actual2 = ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(baseString, actual2.substring(0, baseString.length()));
        assertEquals('[', actual2.charAt(baseString.length()));
        assertEquals(']', actual2.charAt(actual2.length() - 1));
        final String[] fields2 = actual2.substring(baseString.length() + 1, actual2.length() - 1).split(",");
        assertEquals(4, fields2.length);
        assertEquals(
            new HashSet<>(Arrays.asList("staticString2=staticString2", "staticInt2=67890", "staticString=staticString", "staticInt=12345")),
            new HashSet<>(Arrays.asList(fields2)));

        final String actual3 = this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(baseString, actual3.substring(0, baseString.length()));
