    @Test
    public void handlesMethodNotAllowedWithHeaders() throws Exception {
        final Throwable thrown = catchThrowable(() -> target("/exception/json-mapping-exception")
            .request(MediaType.APPLICATION_JSON)
            .post(Entity.json("A"), String.class));
        assertThat(thrown).isInstanceOf(WebApplicationException.class);
        final Response resp = ((WebApplicationException) thrown).getResponse();
        assertThat(resp.getStatus()).isEqualTo(405);

        final String allow = resp.getHeaderString("Allow");
        assertThat(allow).isNotNull();
        assertThat(Arrays.asList(allow.split("\\s*,\\s*"))).containsExactlyInAnyOrder("GET", "OPTIONS");

        final JsonNode json = new ObjectMapper().readTree(resp.readEntity(String.class));
        assertThat(json.get("code").asInt()).isEqualTo(405);
        assertThat(json.get("message").asText()).isEqualTo("HTTP 405 Method Not Allowed");
        assertThat(json.size()).isEqualTo(2);
    }
