    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();
        final java.util.function.UnaryOperator<String> normalizeFieldOrder = value -> {
            final int start = value.indexOf('[');
            final int end = value.lastIndexOf(']');
            final String prefix = value.substring(0, start);
            final String contents = value.substring(start + 1, end);
            final String[] fields = contents.split(",", -1);
            java.util.Arrays.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
        };
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
