  @Test
  public void testAvroDoc() {
    Schema schema = new ReflectData().getSchema(DocTest.class);

    assertEquals(Schema.Type.RECORD, schema.getType());
    assertEquals("DocTest", schema.getName());
    assertEquals("org.apache.avro.reflect.TestReflect", schema.getNamespace());
    assertEquals("org.apache.avro.reflect.TestReflect.DocTest", schema.getFullName());
    assertEquals("DocTest class docs", schema.getDoc());
    assertEquals(3, schema.getFields().size());

    Schema.Field foo = schema.getField("foo");
    assertNotNull(foo);
    assertEquals(Schema.Type.INT, foo.schema().getType());
    assertEquals("Some Documentation", foo.doc());

    Schema.Field enums = schema.getField("enums");
    assertNotNull(enums);
    assertEquals("Some other Documentation", enums.doc());
    Schema enumSchema = enums.schema();
    assertEquals(Schema.Type.ENUM, enumSchema.getType());
    assertEquals("DocTestEnum", enumSchema.getName());
    assertEquals(Arrays.asList("ENUM_1", "ENUM_2"), enumSchema.getEnumSymbols());

    Schema.Field defaultTest = schema.getField("defaultTest");
    assertNotNull(defaultTest);
    assertEquals("And again", defaultTest.doc());
    Schema defaultSchema = defaultTest.schema();
    assertEquals(Schema.Type.RECORD, defaultSchema.getType());
    assertEquals("DefaultTest", defaultSchema.getName());

    Schema.Field nestedFoo = defaultSchema.getField("foo");
    assertNotNull(nestedFoo);
    assertEquals(Schema.Type.INT, nestedFoo.schema().getType());
    assertEquals(1, ((Number) nestedFoo.defaultVal()).intValue());
  }
