  @Test
  public void testAssembleLongPollRefreshUrlWithMultipleNamespaces() throws Exception {
    String someUri = someServerUrl;
    String someAppId = "someAppId";
    String someCluster = "someCluster+ &.-_someSign";
    String someNamespace = "someName";
    String anotherNamespace = "anotherName";
    long someNotificationId = 1;
    long anotherNotificationId = 2;
    Map<String, Long> notificationsMap =
        ImmutableMap.of(someNamespace, someNotificationId, anotherNamespace, anotherNotificationId);

    String longPollRefreshUrl =
        remoteConfigLongPollService
            .assembleLongPollRefreshUrl(someUri, someAppId, someCluster, null, notificationsMap);

    assertTrue(longPollRefreshUrl.contains(someServerUrl + "/notifications/v2?"));
    assertTrue(longPollRefreshUrl.contains("appId=" + someAppId));
    assertTrue(longPollRefreshUrl.contains("cluster=someCluster%2B+%26.-_someSign"));

    String query = longPollRefreshUrl.substring(longPollRefreshUrl.indexOf('?') + 1);
    String encodedNotifications = null;
    for (String parameter : query.split("&")) {
      if (parameter.startsWith("notifications=")) {
        encodedNotifications = parameter.substring("notifications=".length());
        break;
      }
    }
    assertNotNull(encodedNotifications);

    String notificationsJson = java.net.URLDecoder.decode(encodedNotifications, "UTF-8");

    String someNotification =
        "{\"namespaceName\":\"" + someNamespace + "\",\"notificationId\":" + someNotificationId + "}";
    String someNotificationWithReorderedFields =
        "{\"notificationId\":" + someNotificationId + ",\"namespaceName\":\"" + someNamespace + "\"}";
    String anotherNotification =
        "{\"namespaceName\":\"" + anotherNamespace + "\",\"notificationId\":" + anotherNotificationId + "}";
    String anotherNotificationWithReorderedFields =
        "{\"notificationId\":" + anotherNotificationId + ",\"namespaceName\":\"" + anotherNamespace + "\"}";

    assertTrue(
        notificationsJson.contains(someNotification)
            || notificationsJson.contains(someNotificationWithReorderedFields));
    assertTrue(
        notificationsJson.contains(anotherNotification)
            || notificationsJson.contains(anotherNotificationWithReorderedFields));
  }
