    @Test
    public void shouldJsonSerialiseAndDeserialise() throws IOException {
        // Given
        final Object[] controlData = {1, new CustomObj(), 3};
        final IsIn filter = new IsIn(Arrays.asList(controlData));

        // When
        final String json = JsonSerialiser.serialise(filter);

        // Then
        final String expectedJson = String.format("{%n" +
                "  \"class\" : \"uk.gov.gchq.koryphe.impl.predicate.IsIn\",%n" +
                "  \"values\" : [ 1, {\"uk.gov.gchq.koryphe.util.CustomObj\":{\"value\":\"1\"}}, 3 ]%n" +
                "}");
        final ObjectMapper objectMapper = new ObjectMapper();
        final JsonNode expectedJsonNode = objectMapper.readTree(expectedJson);
        final JsonNode actualJsonNode = objectMapper.readTree(json);

        assertThat(actualJsonNode.isObject()).isTrue();
        final List<String> expectedFieldNames = new ArrayList<>();
        expectedJsonNode.fieldNames().forEachRemaining(expectedFieldNames::add);
        final List<String> actualFieldNames = new ArrayList<>();
        actualJsonNode.fieldNames().forEachRemaining(actualFieldNames::add);
        assertThat(actualFieldNames).containsExactlyInAnyOrderElementsOf(expectedFieldNames);
        assertThat(actualJsonNode.size()).isEqualTo(expectedJsonNode.size());
        assertThat(actualJsonNode.get("class")).isEqualTo(expectedJsonNode.get("class"));

        assertThat(actualJsonNode.get("values").isArray()).isTrue();
        final List<JsonNode> expectedValues = new ArrayList<>();
        for (final JsonNode value : expectedJsonNode.get("values")) {
            expectedValues.add(value);
        }
        final List<JsonNode> actualValues = new ArrayList<>();
        for (final JsonNode value : actualJsonNode.get("values")) {
            actualValues.add(value);
        }
        assertThat(actualValues).containsExactlyInAnyOrderElementsOf(expectedValues);

        // When 2
        final IsIn deserialisedFilter = JsonSerialiser.deserialise(json, IsIn.class);

        // Then 2
        assertThat(deserialisedFilter).isNotNull();
        assertThat(deserialisedFilter.getAllowedValues()).containsExactlyInAnyOrderElementsOf(Arrays.asList(controlData));
    }
