    public void test_list() throws Exception {
        Model model = new Model();
        Map tables = new LinkedHashMap();
        tables.put("1001", new ExtTable(1001));
        tables.put("1002", new Table());
        model.setTables(tables);

        String json = JSON.toJSONString(model);
        assertEquals("{\"tables\":{\"1001\":{\"@type\":\"com.alibaba.json.bvt.writeClassName.WriteClassNameTest_Map$ExtTable\",\"id\":1001},\"1002\":{}}}", json);

        JSONObject jsonObject = JSON.parseObject(json, Feature.IgnoreAutoType);

        class Canonicalizer {
            Object normalize(Object value) {
                if (value instanceof Map) {
                    Map<String, Object> sorted = new TreeMap<String, Object>();
                    for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet()) {
                        sorted.put(String.valueOf(entry.getKey()), normalize(entry.getValue()));
                    }
                    return sorted;
                }
                if (value instanceof Collection) {
                    List<Object> normalized = new ArrayList<Object>();
                    for (Object item : (Collection<?>) value) {
                        normalized.add(normalize(item));
                    }
                    return normalized;
                }
                if (value != null && value.getClass().isArray()) {
                    int length = java.lang.reflect.Array.getLength(value);
                    List<Object> normalized = new ArrayList<Object>(length);
                    for (int i = 0; i < length; i++) {
                        normalized.add(normalize(java.lang.reflect.Array.get(value, i)));
                    }
                    return normalized;
                }
                return value;
            }
        }
        Canonicalizer canonicalizer = new Canonicalizer();
        Object expected = JSON.parse("{\"tables\":{\"1002\":{},\"1001\":{\"id\":1001}}}");
        assertEquals(canonicalizer.normalize(expected), canonicalizer.normalize(jsonObject));

        Model model2 = JSON.parseObject(json, Model.class);
        assertEquals(ExtTable.class, model2.getTables().get("1001").getClass());
    }
