        String suffix = ",1,2)";
        assertTrue("unexpected JSONP output: " + json, json.startsWith(prefix));
        assertTrue("unexpected JSONP output: " + json, json.endsWith(suffix));

        String objectText = json.substring(prefix.length(), json.length() - suffix.length());
        assertTrue("unexpected serialized object: " + objectText,
                objectText.length() >= 2 && objectText.charAt(0) == '{' && objectText.charAt(objectText.length() - 1) == '}');

        String body = objectText.substring(1, objectText.length() - 1);
        String[] entries = body.split(",");
        assertEquals(2, entries.length);

        java.util.TreeMap<String, String> actualEntries = new java.util.TreeMap<String, String>();
        for (String entry : entries) {
            int colon = entry.indexOf(':');
            assertTrue("invalid serialized entry: " + entry, colon > 0);
            actualEntries.put(entry.substring(0, colon), entry.substring(colon + 1));
        }

        java.util.TreeMap<String, String> expectedEntries = new java.util.TreeMap<String, String>();
        expectedEntries.put("\"id\"", "1");
        expectedEntries.put("\"name\"", "\"ido\\u0029nans\"");
