//<fix start>
    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        class ParsedToString {
            private final String prefix;
            private final Map<String, String> fields;

            ParsedToString(final String value) {
                final int start = value.indexOf('[');
                final int end = value.lastIndexOf(']');
                if (start < 0 || end < start) {
                    this.prefix = value;
                    this.fields = new HashMap<>();
                } else {
                    this.prefix = value.substring(0, start);
                    this.fields = new HashMap<>();
                    if (end > start + 1) {
                        for (final String entry : value.substring(start + 1, end).split(",")) {
                            final int eq = entry.indexOf('=');
                            this.fields.put(entry.substring(0, eq), entry.substring(eq + 1));
                        }
                    }
                }
            }

            @Override
            public boolean equals(final Object obj) {
                if (this == obj) {
                    return true;
                }
                if (!(obj instanceof ParsedToString)) {
                    return false;
                }
                final ParsedToString other = (ParsedToString) obj;
                return this.prefix.equals(other.prefix) && this.fields.equals(other.fields);
            }

            @Override
            public int hashCode() {
                return this.prefix.hashCode() * 31 + this.fields.hashCode();
            }
        }

        assertEquals(
            new ParsedToString(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            new ParsedToString(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
