//<fix start>
    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        class ParsedToString {
            private final boolean wellFormed;
            private final String prefix;
            private final List<String> fields;
            private final String suffix;

            ParsedToString(final String value) {
                final int start = value.indexOf('[');
                final int end = value.lastIndexOf(']');
                if (start < 0 || end < start) {
                    this.wellFormed = false;
                    this.prefix = value;
                    this.fields = new ArrayList<>();
                    this.suffix = "";
                } else {
                    this.wellFormed = true;
                    this.prefix = value.substring(0, start);
                    this.suffix = value.substring(end + 1);
                    this.fields = new ArrayList<>();
                    final String fieldString = value.substring(start + 1, end);
                    if (!fieldString.isEmpty()) {
                        for (final String entry : fieldString.split(",", -1)) {
                            this.fields.add(entry);
                        }
                    }
                    this.fields.sort(null);
                }
            }

            @Override
            public boolean equals(final Object obj) {
                if (this == obj) {
                    return true;
                }
                if (!(obj instanceof ParsedToString)) {
                    return false;
                }
                final ParsedToString other = (ParsedToString) obj;
                return this.wellFormed == other.wellFormed
                    && this.prefix.equals(other.prefix)
                    && this.fields.equals(other.fields)
                    && this.suffix.equals(other.suffix);
            }

            @Override
            public int hashCode() {
                int result = Boolean.hashCode(this.wellFormed);
                result = 31 * result + this.prefix.hashCode();
                result = 31 * result + this.fields.hashCode();
                result = 31 * result + this.suffix.hashCode();
                return result;
            }
        }

        assertEquals(
            new ParsedToString(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            new ParsedToString(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            new ParsedToString(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            new ParsedToString(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            new ParsedToString(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            new ParsedToString(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            new ParsedToString(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            new ParsedToString(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
