    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        final java.util.function.Function<String, String> normalizeToString = str -> {
            final int open = str.indexOf('[');
            final int close = str.lastIndexOf(']');
            if (open < 0 || close != str.length() - 1 || open > close) {
                throw new AssertionError("Unexpected toString format: " + str);
            }
            final String prefix = str.substring(0, open);
            final String body = str.substring(open + 1, close);
            if (body.isEmpty()) {
                return prefix + "[]";
            }
            final String[] fields = body.split(",", -1);
            java.util.Arrays.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
        };

        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeToString.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeToString.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeToString.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
