    @Test
    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final java.util.function.Function<String, String> sortFields = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start < 0 || end < start) {
                return s;
            }
            final String[] fields = s.substring(start + 1, end).split(",");
            java.util.Arrays.sort(fields);
            final StringBuilder sb = new StringBuilder(s.length());
            sb.append(s, 0, start + 1);
            for (int i = 0; i < fields.length; i++) {
                if (i > 0) {
                    sb.append(',');
                }
                sb.append(fields[i]);
            }
            sb.append(s, end, s.length());
            return sb.toString();
        };
        final String expected = this.toBaseString(instance1) + "[staticInt=12345,staticString=staticString]";
        assertEquals(
            expected,
            sortFields.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            expected,
            sortFields.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            expected,
            sortFields.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            expected,
            sortFields.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
