    @Test
    public void testReflectionHierarchyHashCode() {
        class LocalHashCodeBase {
            private final int a;

            LocalHashCodeBase(final int a) {
                this.a = a;
            }
        }

        class LocalHashCodeTransient extends LocalHashCodeBase {
            private final transient int c;

            LocalHashCodeTransient(final int a, final int c) {
                super(a);
                this.c = c;
            }
        }

        class LocalHashCodeSub extends LocalHashCodeTransient {
            private final int b;

            LocalHashCodeSub(final int a, final int b, final int c) {
                super(a, c);
                this.b = b;
            }
        }

        assertEquals(17 * 37 * 37, HashCodeBuilder.reflectionHashCode(new LocalHashCodeSub(0, 0, 0)));
        assertEquals(17 * 37 * 37 * 37, HashCodeBuilder.reflectionHashCode(new LocalHashCodeSub(0, 0, 0), true));
        assertEquals((17 * 37 + 7890) * 37 + 123456, HashCodeBuilder.reflectionHashCode(new LocalHashCodeSub(123456, 7890,
                0)));
        assertEquals(((17 * 37 + 7890) * 37 + 0) * 37 + 123456, HashCodeBuilder.reflectionHashCode(new LocalHashCodeSub(
                123456, 7890, 0), true));
    }
