//<fix start>
    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final java.util.function.UnaryOperator<String> canonicalize = s -> {
            final int firstBreak = s.indexOf(BR);
            final int lastBreak = s.lastIndexOf(BR);
            if (firstBreak < 0 || lastBreak <= firstBreak) {
                return s;
            }

            final String body = s.substring(firstBreak + BR.length(), lastBreak);
            final List<String> fields = new ArrayList<>();
            int depth = 0;
            int start = 0;

            for (int i = 0; i < body.length(); i++) {
                final char c = body.charAt(i);
                if (c == '{') {
                    depth++;
                } else if (c == '}') {
                    depth--;
                } else if (c == ',' && depth == 0) {
                    String field = body.substring(start, i);
                    if (field.startsWith(BR)) {
                        field = field.substring(BR.length());
                    }
                    fields.add(field);
                    start = i + 1;
                }
            }

            String lastField = body.substring(start);
            if (lastField.startsWith(BR)) {
                lastField = lastField.substring(BR.length());
            }
            fields.add(lastField);

            fields.sort((a, b) -> {
                final int aEq = a.indexOf('=');
                final int bEq = b.indexOf('=');
                final String aName = aEq < 0 ? a.trim() : a.substring(0, aEq).trim();
                final String bName = bEq < 0 ? b.trim() : b.substring(0, bEq).trim();
                return aName.compareTo(bName);
            });

            final StringBuilder result = new StringBuilder();
            result.append(s, 0, firstBreak + BR.length());
            for (int i = 0; i < fields.size(); i++) {
                result.append(fields.get(i));
                if (i < fields.size() - 1) {
                    result.append(',').append(BR);
                }
            }
            result.append(BR).append(']');
            return result.toString();
        };

        assertEquals(canonicalize.apply(exp), canonicalize.apply(toString(wa)));
    }
