//<fix start>
    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";

        final java.util.function.UnaryOperator<String> canonicalize = s -> {
            final int open = s.indexOf('[');
            final int close = s.lastIndexOf(']');
            if (open < 0 || close < 0 || close < open) {
                return "INVALID:" + s;
            }

            final String prefix = s.substring(0, open + 1);
            final String suffix = s.substring(close);
            final String body = s.substring(open + 1, close);

            if (!body.startsWith(BR) || !body.endsWith(BR)) {
                return "INVALID_BODY:" + s;
            }

            final String inner = body.substring(BR.length(), body.length() - BR.length());
            final List<String> fields = new ArrayList<>();
            if (!inner.isEmpty()) {
                final String sep = "," + BR;
                int depth = 0;
                int start = 0;
                for (int i = 0; i < inner.length(); i++) {
                    final char c = inner.charAt(i);
                    if (c == '{') {
                        depth++;
                    } else if (c == '}') {
                        depth--;
                    } else if (depth == 0 && c == ',' && inner.startsWith(sep, i)) {
                        fields.add(inner.substring(start, i));
                        i += sep.length() - 1;
                        start = i + 1;
                    }
                }
                fields.add(inner.substring(start));
            }

            fields.sort((a, b) -> {
                final int aEq = a.indexOf('=');
                final int bEq = b.indexOf('=');
                final String aName = aEq < 0 ? a.trim() : a.substring(0, aEq).trim();
                final String bName = bEq < 0 ? b.trim() : b.substring(0, bEq).trim();
                final int byName = aName.compareTo(bName);
                return byName != 0 ? byName : a.compareTo(b);
            });

            final StringBuilder result = new StringBuilder();
            result.append(prefix.length()).append(':').append(prefix);
            result.append('|').append(fields.size()).append('|');
            for (final String field : fields) {
                result.append(field.length()).append(':').append(field);
            }
            result.append('|').append(suffix.length()).append(':').append(suffix);
            return result.toString();
        };

        assertEquals(canonicalize.apply(exp), canonicalize.apply(toString(wa)));
    }
