            final List<String> fields = new ArrayList<>();
            for (final String field : s.substring(start + 1, end).split(",")) {
                fields.add(field);
            }
            java.util.Collections.sort(fields);
            return fields;
        };
        final java.util.function.Function<String, String> prefix = s -> s.substring(0, s.indexOf('['));

        final String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class);
        assertEquals(this.toBaseString(instance1), prefix.apply(actual1));
        assertEquals(java.util.Arrays.asList(
            "instanceInt=67890",
            "instanceString=instanceString",
            "staticInt=12345",
            "staticString=staticString"), sortedFields.apply(actual1));

        final String actual2 = ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class);
        assertEquals(this.toBaseString(instance1), prefix.apply(actual2));
        assertEquals(java.util.Arrays.asList(
            "instanceInt=67890",
            "instanceString=instanceString",
            "staticInt=12345",
            "staticString=staticString",
            "staticTransientInt=54321",
            "staticTransientString=staticTransientString",
            "transientInt=98765",
            "transientString=transientString"), sortedFields.apply(actual2));

        final String actual3 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        assertEquals(this.toBaseString(instance1), prefix.apply(actual3));
        assertEquals(java.util.Arrays.asList(
            "instanceInt=67890",
