        final List<Object> list = new ArrayList<>(ARRAYLIST_INITIAL_CAPACITY);
        final String baseString = this.toBaseString(list);

        final String expectedWithTransients = baseString + "[elementData={<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>},modCount=0,size=0]";
        final String toStringWithTransients = ToStringBuilder.reflectionToString(list, null, true);

        final int open = toStringWithTransients.indexOf('[');
        final int close = toStringWithTransients.lastIndexOf(']');
        final String prefix = toStringWithTransients.substring(0, open + 1);
        final String fieldsString = toStringWithTransients.substring(open + 1, close);

        final List<String> fields = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < fieldsString.length(); i++) {
            final char c = fieldsString.charAt(i);
            if (c == '{' || c == '[' || c == '(') {
                depth++;
            } else if (c == '}' || c == ']' || c == ')') {
                depth--;
            } else if (c == ',' && depth == 0) {
                fields.add(fieldsString.substring(start, i));
                start = i + 1;
            }
        }
        if (!fieldsString.isEmpty()) {
            fields.add(fieldsString.substring(start));
        }

        java.util.Collections.sort(fields);
        final String actualWithTransients = prefix + String.join(",", fields) + toStringWithTransients.substring(close);
        assertEquals(expectedWithTransients, actualWithTransients);

        final String expectedWithoutTransients = baseString + "[size=0]";
        final String toStringWithoutTransients = ToStringBuilder.reflectionToString(list, null, false);
