//<fix start>
    @Test
    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        final java.util.function.Function<java.util.Set<String>, Integer> expectedHashCode = excludeFieldNames -> {
            int hashCode = 17;
            for (Class<?> clazz = x.getClass(); clazz != null && clazz != Object.class; clazz = clazz.getSuperclass()) {
                for (final java.lang.reflect.Field field : clazz.getDeclaredFields()) {
                    final int modifiers = field.getModifiers();
                    if (!excludeFieldNames.contains(field.getName())
                            && !java.lang.reflect.Modifier.isStatic(modifiers)
                            && !java.lang.reflect.Modifier.isTransient(modifiers)
                            && !field.isSynthetic()) {
                        try {
                            field.setAccessible(true);
                            hashCode = hashCode * 37 + ((Number) field.get(x)).intValue();
                        } catch (final IllegalAccessException e) {
                            throw new AssertionError(e);
                        }
                    }
                }
            }
            return hashCode;
        };

        assertEquals(expectedHashCode.apply(java.util.Collections.emptySet()), HashCodeBuilder.reflectionHashCode(x));

        assertEquals(expectedHashCode.apply(java.util.Collections.emptySet()), HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(expectedHashCode.apply(java.util.Collections.emptySet()), HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedHashCode.apply(java.util.Collections.singleton("xxx")), HashCodeBuilder.reflectionHashCode(x, "xxx"));

        assertEquals(expectedHashCode.apply(java.util.Collections.singleton("two")), HashCodeBuilder.reflectionHashCode(x, "two"));
        assertEquals(expectedHashCode.apply(java.util.Collections.singleton("three")), HashCodeBuilder.reflectionHashCode(x, "three"));

