//<fix start>
	@Test
	public void testImport() throws Exception {
		ClassPathResource resource = new ClassPathResource("importing.xsd", getClass());
		CommonsXsdSchemaCollection schemaCollection = new CommonsXsdSchemaCollection(resource);
		schemaCollection.setInline(true);
		schemaCollection.afterPropertiesSet();
		definition.setSchemaCollection(schemaCollection);

		definition.setPortTypeName("Order");
		definition.setTargetNamespace("http://www.springframework.org/spring-ws/import/definitions");
		definition.setLocationUri("http://localhost:8080/");
		definition.afterPropertiesSet();

		DOMResult domResult = new DOMResult();
		transformer.transform(definition.getSource(), domResult);

		Document result = (Document) domResult.getNode();
		Document expected = documentBuilder.parse(getClass().getResourceAsStream("import-inline.wsdl"));

		class WsdlOrderNormalizer {
			void normalize(Document document) {
				Element definitions = document.getDocumentElement();
				List<Element> allElements = new ArrayList<Element>();
				NodeList elements = document.getElementsByTagNameNS("*", "*");
				for (int i = 0; i < elements.getLength(); i++) {
					allElements.add((Element) elements.item(i));
				}
				for (int i = 0; i < allElements.size(); i++) {
					Element element = allElements.get(i);
					String localName = element.getLocalName();
					if ("message".equals(localName)) {
						sortChildren(element, "part");
					}
					else if ("portType".equals(localName) || "binding".equals(localName)) {
						sortChildren(element, "operation");
					}
					else if ("operation".equals(localName)) {
						sortChildren(element, "fault");
					}
					else if ("service".equals(localName)) {
						sortChildren(element, "port");
					}
				}
				sortChildren(definitions, "message");
			}

			private void sortChildren(Element parent, String localName) {
				List<Node> children = new ArrayList<Node>();
				NodeList nodeList = parent.getChildNodes();
				for (int i = 0; i < nodeList.getLength(); i++) {
					children.add(nodeList.item(i));
				}
				List<Element> matching = new ArrayList<Element>();
				for (int i = 0; i < children.size(); i++) {
					Node child = children.get(i);
					if (child.getNodeType() == Node.ELEMENT_NODE
							&& localName.equals(((Element) child).getLocalName())) {
						matching.add((Element) child);
					}
				}
				Collections.sort(matching, new Comparator<Element>() {
					public int compare(Element left, Element right) {
						String leftName = left.getAttribute("name");
						String rightName = right.getAttribute("name");
						return leftName.compareTo(rightName);
					}
				});
				for (int i = 0; i < children.size(); i++) {
					parent.removeChild(children.get(i));
				}
				int matchingIndex = 0;
				for (int i = 0; i < children.size(); i++) {
					Node child = children.get(i);
					if (child.getNodeType() == Node.ELEMENT_NODE
							&& localName.equals(((Element) child).getLocalName())) {
						parent.appendChild(matching.get(matchingIndex++));
					}
					else {
						parent.appendChild(child);
					}
				}
			}
		}

		WsdlOrderNormalizer normalizer = new WsdlOrderNormalizer();
		normalizer.normalize(expected);
		normalizer.normalize(result);

		assertXMLEqual("Invalid WSDL built", expected, result);
	}
