    @Test
    public void testReflectionHierarchy() {
        final java.util.function.UnaryOperator<String> sortEntries = s -> {
            final int open = s.indexOf('[');
            final int close = s.lastIndexOf(']');
            if (open < 0 || close < open) {
                return s;
            }
            final String body = s.substring(open + 1, close);
            final String[] entries = body.isEmpty() ? new String[0] : body.split(",", -1);
            java.util.Arrays.sort(entries);
            return s.substring(0, open + 1) + String.join(",", entries) + s.substring(close);
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA)));
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null)));
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null, false)));
        assertEquals(baseString + "[a=a,transientA=t]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null, true)));
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null, false, null)));
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null, false, Object.class)));
        assertEquals(baseString + "[a=a]", sortEntries.apply(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class)));

