//<fix start>
  @Test
  public void testAvroDoc() throws IOException {
    String expected = "{\"type\":\"record\",\"name\":\"DocTest\",\"namespace\":\"org.apache.avro.reflect.TestReflect\","
        + "\"doc\":\"DocTest class docs\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"doc\":\"Some Documentation\"},"
        + "{\"name\":\"enums\",\"type\":{\"type\":\"enum\",\"name\":\"DocTestEnum\","
        + "\"symbols\":[\"ENUM_1\",\"ENUM_2\"]},\"doc\":\"Some other Documentation\"},"
        + "{\"name\":\"defaultTest\",\"type\":{\"type\":\"record\",\"name\":\"DefaultTest\","
        + "\"fields\":[{\"name\":\"foo\",\"type\":\"int\",\"default\":1}]},\"doc\":\"And again\"}]}";

    ObjectMapper mapper = new ObjectMapper();

    class Canonicalizer {
      JsonNode normalize(JsonNode node) {
        if (node == null) {
          return null;
        }
        if (node.isObject()) {
          ObjectNode result = JsonNodeFactory.instance.objectNode();
          Iterator<Map.Entry<String, JsonNode>> fields = node.fields();
          while (fields.hasNext()) {
            Map.Entry<String, JsonNode> field = fields.next();
            JsonNode value = normalize(field.getValue());
            if ("fields".equals(field.getKey()) && value != null && value.isArray()) {
              List<JsonNode> sorted = new ArrayList<>();
              for (JsonNode element : value) {
                sorted.add(element);
              }
              Collections.sort(sorted, new Comparator<JsonNode>() {
                @Override
                public int compare(JsonNode left, JsonNode right) {
                  return left.get("name").asText().compareTo(right.get("name").asText());
                }
              });
              ArrayNode sortedFields = JsonNodeFactory.instance.arrayNode();
              for (JsonNode element : sorted) {
                sortedFields.add(element);
              }
              value = sortedFields;
            }
            result.set(field.getKey(), value);
          }
          return result;
        }
        if (node.isArray()) {
          ArrayNode result = JsonNodeFactory.instance.arrayNode();
          for (JsonNode element : node) {
            result.add(normalize(element));
          }
          return result;
        }
        return node;
      }
    }

    Canonicalizer canonicalizer = new Canonicalizer();
    JsonNode expectedSchema = canonicalizer.normalize(mapper.readTree(expected));
    JsonNode actualSchema = canonicalizer.normalize(
        mapper.readTree(ReflectData.get().getSchema(DocTest.class).toString()));
    assertEquals(expectedSchema, actualSchema);
  }
