    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();
        final java.util.Map<String, Integer> fieldGroups = new java.util.HashMap<>();
        fieldGroups.put("staticString2", 0);
        fieldGroups.put("staticInt2", 0);
        fieldGroups.put("staticString", 1);
        fieldGroups.put("staticInt", 1);
        final java.util.function.UnaryOperator<String> normalizeFieldOrder = value -> {
            final int start = value.indexOf('[');
            final int end = value.lastIndexOf(']');
            final String prefix = value.substring(0, start);
            final String contents = value.substring(start + 1, end);
            if (contents.isEmpty()) {
                return prefix + "[]";
            }
            final String[] fields = contents.split(",");
            final java.util.List<java.util.List<String>> groups = new java.util.ArrayList<>();
            final java.util.List<Integer> groupIndices = new java.util.ArrayList<>();
            int currentGroup = Integer.MIN_VALUE;
            java.util.List<String> currentFields = null;
            for (final String field : fields) {
                final int eq = field.indexOf('=');
                final String fieldName = eq >= 0 ? field.substring(0, eq) : field;
                final int group = fieldGroups.getOrDefault(fieldName, Integer.MAX_VALUE);
                if (group != currentGroup) {
                    currentGroup = group;
                    currentFields = new java.util.ArrayList<>();
                    groups.add(currentFields);
                    groupIndices.add(group);
                }
                currentFields.add(field);
            }
            final StringBuilder sb = new StringBuilder(prefix);
            sb.append('[');
            boolean first = true;
            for (int i = 0; i < groups.size(); i++) {
                if (!first) {
                    sb.append('|');
                }
                first = false;
                final java.util.List<String> groupFields = groups.get(i);
                java.util.Collections.sort(groupFields);
                sb.append(groupIndices.get(i)).append(':').append(String.join(",", groupFields));
            }
            sb.append(']');
            return sb.toString();
        };
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
