        expectedFieldValues.put("staticInt2", "67890");
        expectedFieldValues.put("staticString", "staticString");
        expectedFieldValues.put("staticInt", "12345");
        final String prefix = this.toBaseString(instance1);
        final java.util.function.Function<Class<?>, String> expectedString = upToClass -> {
            final StringBuilder sb = new StringBuilder(prefix);
            sb.append('[');
            boolean first = true;
            Class<?> clazz = instance1.getClass();
            while (true) {
                for (final java.lang.reflect.Field field : clazz.getDeclaredFields()) {
                    final String fieldName = field.getName();
                    if (java.lang.reflect.Modifier.isStatic(field.getModifiers())
                            && expectedFieldValues.containsKey(fieldName)) {
                        if (!first) {
                            sb.append(',');
                        }
                        first = false;
                        sb.append(fieldName).append('=').append(expectedFieldValues.get(fieldName));
                    }
                }
                if (clazz == upToClass) {
                    break;
                }
                clazz = clazz.getSuperclass();
            }
            sb.append(']');
            return sb.toString();
        };
        assertEquals(
            expectedString.apply(InheritedReflectionStaticFieldsFixture.class),
            ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class));
        assertEquals(
            expectedString.apply(SimpleReflectionStaticFieldsFixture.class),
            ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class));
        assertEquals(
            expectedString.apply(SimpleReflectionStaticFieldsFixture.class),
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
        assertEquals(
            expectedString.apply(SimpleReflectionStaticFieldsFixture.class),
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
    }
