  public void testAssembleLongPollRefreshUrlWithMultipleNamespaces() throws Exception {
    String someUri = someServerUrl;
    String someAppId = "someAppId";
    String someCluster = "someCluster+ &.-_someSign";
    String someNamespace = "someName";
    String anotherNamespace = "anotherName";
    long someNotificationId = 1;
    long anotherNotificationId = 2;
    Map<String, Long> notificationsMap =
        ImmutableMap.of(someNamespace, someNotificationId, anotherNamespace, anotherNotificationId);

    String longPollRefreshUrl =
        remoteConfigLongPollService
            .assembleLongPollRefreshUrl(someUri, someAppId, someCluster, null, notificationsMap);

    assertTrue(longPollRefreshUrl.contains(someServerUrl + "/notifications/v2?"));
    assertTrue(longPollRefreshUrl.contains("appId=" + someAppId));
    assertTrue(longPollRefreshUrl.contains("cluster=someCluster%2B+%26.-_someSign"));

    String notificationsJson = null;
    String queryString = longPollRefreshUrl.substring(longPollRefreshUrl.indexOf('?') + 1);
    for (String parameter : queryString.split("&")) {
      int equalsIndex = parameter.indexOf('=');
      if (equalsIndex < 0) {
        continue;
      }

      String parameterName = URLDecoder.decode(parameter.substring(0, equalsIndex), "UTF-8");
      if ("notifications".equals(parameterName)) {
        notificationsJson = URLDecoder.decode(parameter.substring(equalsIndex + 1), "UTF-8");
        break;
      }
    }

    assertNotNull(notificationsJson);

    ApolloConfigNotification[] notifications =
        new Gson().fromJson(notificationsJson, ApolloConfigNotification[].class);
    assertEquals(2, notifications.length);

    Map<String, Long> actualNotifications = new HashMap<>();
    for (ApolloConfigNotification notification : notifications) {
      actualNotifications.put(
          notification.getNamespaceName(), notification.getNotificationId());
    }

    assertEquals(notificationsMap, actualNotifications);
  }
