        final String isolatedMarker = "hudson.remoting.DiagnosedStreamCorruptionExceptionTest.isolated";
        if (Boolean.getBoolean(isolatedMarker)) {
            ClassicCommandTransport ct = (ClassicCommandTransport)
                    new ChannelBuilder("dummy", null)
                        .withMode(Mode.BINARY)
                        .withBaseLoader(getClass().getClassLoader())
                        .negotiate(new ByteArrayInputStream(payload), new NullOutputStream());

            verify(ct);
            return;
        }

        System.clearProperty("hudson.remoting.ClassFilter.DEFAULT");

        ClassLoader parent = getClass().getClassLoader();
        ClassLoader isolated = new ClassLoader(parent) {
            @Override
            protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
                if (name.startsWith("hudson.remoting.")) {
                    synchronized (getClassLoadingLock(name)) {
                        Class<?> c = findLoadedClass(name);
                        if (c == null) {
                            String resourceName = name.replace('.', '/') + ".class";
                            try (java.io.InputStream is = parent.getResourceAsStream(resourceName)) {
                                if (is != null) {
                                    byte[] bytes = org.apache.commons.io.IOUtils.toByteArray(is);
                                    c = defineClass(name, bytes, 0, bytes.length);
                                } else {
                                    c = parent.loadClass(name);
                                }
                            } catch (java.io.IOException e) {
                                throw new ClassNotFoundException(name, e);
                            }
                        }
                        if (resolve) {
                            resolveClass(c);
                        }
                        return c;
                    }
                }
                return super.loadClass(name, resolve);
            }
        };

        Class<?> testClass = Class.forName("hudson.remoting.DiagnosedStreamCorruptionExceptionTest", true, isolated);
        java.lang.reflect.Constructor<?> ctor = testClass.getDeclaredConstructor();
        ctor.setAccessible(true);
        Object testInstance = ctor.newInstance();
        java.lang.reflect.Method method = testClass.getDeclaredMethod("exercise");
        method.setAccessible(true);
        System.setProperty(isolatedMarker, "true");
        try {
            method.invoke(testInstance);
        } catch (java.lang.reflect.InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof Exception) {
                throw (Exception) cause;
            }
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            throw new RuntimeException(cause);
        } finally {
            System.clearProperty(isolatedMarker);
        }
