//<fix start>
    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        java.lang.reflect.Field typeField = BeanCacheKey.class.getDeclaredField("type");
        typeField.setAccessible(true);
        java.lang.reflect.Field pathField = BeanCacheKey.class.getDeclaredField("path");
        pathField.setAccessible(true);
        java.lang.reflect.Field delegateField = BeanCacheKey.class.getDeclaredField("delegate");
        delegateField.setAccessible(true);
        java.lang.reflect.Field qualifiersField = BeanCacheKey.class.getDeclaredField("qualifiers");
        qualifiersField.setAccessible(true);

        java.util.List<Annotation> aQualifiers = new java.util.ArrayList<Annotation>();
        java.util.List<Annotation> bQualifiers = new java.util.ArrayList<Annotation>();
        Object aq = qualifiersField.get(a);
        Object bq = qualifiersField.get(b);
        if (aq instanceof java.util.Collection)
        {
            for (Object q : (java.util.Collection<?>) aq)
            {
                aQualifiers.add((Annotation) q);
            }
            for (Object q : (java.util.Collection<?>) bq)
            {
                bQualifiers.add((Annotation) q);
            }
        }
        else if (aq != null && aq.getClass().isArray())
        {
            for (int i = 0; i < java.lang.reflect.Array.getLength(aq); i++)
            {
                aQualifiers.add((Annotation) java.lang.reflect.Array.get(aq, i));
            }
            for (int i = 0; i < java.lang.reflect.Array.getLength(bq); i++)
            {
                bQualifiers.add((Annotation) java.lang.reflect.Array.get(bq, i));
            }
        }
        else
        {
            aQualifiers.add((Annotation) aq);
            bQualifiers.add((Annotation) bq);
        }

        Assert.assertEquals(typeField.get(a), typeField.get(b));
        Assert.assertEquals(pathField.get(a), pathField.get(b));
        Assert.assertEquals(delegateField.get(a), delegateField.get(b));
        Assert.assertEquals(aQualifiers.size(), bQualifiers.size());
        for (Annotation qualifier : aQualifiers)
        {
            Assert.assertTrue(bQualifiers.remove(qualifier));
        }
        Assert.assertTrue(bQualifiers.isEmpty());
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
