    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        Class<?> currentClass = BeanCacheKey.class;
        while (currentClass != null)
        {
            java.lang.reflect.Field[] fields = currentClass.getDeclaredFields();
            for (java.lang.reflect.Field field : fields)
            {
                field.setAccessible(true);
                Object av = field.get(a);
                Object bv = field.get(b);

                if (av instanceof java.util.Collection && bv instanceof java.util.Collection)
                {
                    java.util.List<Object> aValues = new java.util.ArrayList<Object>((java.util.Collection<?>) av);
                    java.util.List<Object> bValues = new java.util.ArrayList<Object>((java.util.Collection<?>) bv);
                    Assert.assertEquals("size of field " + field.getName(), aValues.size(), bValues.size());
                    for (Object aValue : aValues)
                    {
                        Assert.assertTrue("missing value in field " + field.getName() + ": " + aValue, bValues.remove(aValue));
                    }
                    Assert.assertTrue("extra values in field " + field.getName(), bValues.isEmpty());
                }
                else if (av != null && bv != null && av.getClass().isArray() && bv.getClass().isArray())
                {
                    int aLength = java.lang.reflect.Array.getLength(av);
                    int bLength = java.lang.reflect.Array.getLength(bv);
                    Assert.assertEquals("length of field " + field.getName(), aLength, bLength);
                    java.util.List<Object> aValues = new java.util.ArrayList<Object>();
                    java.util.List<Object> bValues = new java.util.ArrayList<Object>();
                    for (int i = 0; i < aLength; i++)
                    {
                        aValues.add(java.lang.reflect.Array.get(av, i));
                        bValues.add(java.lang.reflect.Array.get(bv, i));
                    }
                    for (Object aValue : aValues)
                    {
                        Assert.assertTrue("missing value in field " + field.getName() + ": " + aValue, bValues.remove(aValue));
                    }
                    Assert.assertTrue("extra values in field " + field.getName(), bValues.isEmpty());
                }
                else
                {
                    Assert.assertEquals("field " + field.getName(), av, bv);
                }
            }
            currentClass = currentClass.getSuperclass();
        }

        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
