def test_next_code(coder):
    import sqlite3

    def reset_codes():
        session = getattr(coder, "session", None)
        if session is None:
            session = getattr(coder, "_session", None)
        if session is not None:
            if hasattr(session, "rollback"):
                session.rollback()
            if hasattr(session, "expire_all"):
                session.expire_all()

        engine = getattr(coder, "engine", None)
        if engine is None:
            engine = getattr(coder, "_engine", None)
        if engine is not None and hasattr(engine, "dispose"):
            engine.dispose()

        db_path = "tests/codes.sqlite"
        if os.path.exists(db_path):
            connection = sqlite3.connect(db_path)
            try:
                table_rows = connection.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()
                for (table_name,) in table_rows:
                    connection.execute(f'DELETE FROM "{table_name}"')
                connection.commit()
            finally:
                connection.close()

        if session is not None and hasattr(session, "expire_all"):
            session.expire_all()

    reset_codes()
    coder.next_code("init code test")
    coder.next_code()
    code = coder.next_code("next code test")
    assert code == "52ZA1"
    reset_codes()
#<victim end>
