    @Test(timeout=3000)
    public void blockingStreamShouldNotPreventDiagnosis() throws Exception {
        // DefaultClassFilterTest can poison ClassFilter by triggering a VM class-initialization
        // error while the override property contains an invalid regex. Reset that shared state
        // before this test touches ChannelBuilder/ClassFilter.
        System.clearProperty("hudson.remoting.ClassFilter");
        Class<?> classFilterClass = getClass().getClassLoader().loadClass("hudson.remoting.ClassFilter");
        java.lang.reflect.Field unsafeField = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
        unsafeField.setAccessible(true);
        sun.misc.Unsafe unsafe = (sun.misc.Unsafe) unsafeField.get(null);
        java.lang.reflect.Field initStateField = Class.class.getDeclaredField("init_state");
        initStateField.setAccessible(true);
        long initStateOffset = unsafe.objectFieldOffset(initStateField);
        unsafe.putInt(classFilterClass, initStateOffset, 0);
        Class.forName("hudson.remoting.ClassFilter", true, getClass().getClassLoader());

        try (FastPipedInputStream in = new FastPipedInputStream();
            FastPipedOutputStream out = new FastPipedOutputStream(in)) {
            out.write(payload);

            ClassicCommandTransport ct = (ClassicCommandTransport)
                    new ChannelBuilder("dummy",null)
                        .withMode(Mode.BINARY)
                        .withBaseLoader(getClass().getClassLoader())
                        .negotiate(in, new NullOutputStream());

            verify(ct);
        }
    }
