            if isinstance(obj, MemoryReporter):
                found_issues = getattr(obj, "found_issues", None)
                if isinstance(found_issues, dict):
                    for key in list(found_issues):
                        found_issues[key] = 0
                    for category in Category:
                        found_issues[category] = 0
                messages = getattr(obj, "messages", None)
                if isinstance(messages, list):
                    messages.clear()

        for cls in MemoryReporter.__mro__:
            cls_found_issues = cls.__dict__.get("found_issues")
            if isinstance(cls_found_issues, dict):
                for key in list(cls_found_issues):
                    cls_found_issues[key] = 0
                for category in Category:
                    cls_found_issues[category] = 0
            cls_messages = cls.__dict__.get("messages")
            if isinstance(cls_messages, list):
                cls_messages.clear()

        cli_args = _create_arg_parser().parse_args(["test_rule_without_fix"])
        reload(config)
        config.REPORTER = MemoryReporter
        linter = Linter(cli_args, config)
        lines, reporter = linter.lint_lines("test_rule_without_fix", self.TEST_INPUT)

