//<fix start>
@Test
public void testEquals2Annotations() throws Exception
{
    BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
    BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

    // Order-insensitive but complete comparison for the two-annotation keys.
    Class<?> currentClass = BeanCacheKey.class;
    while (currentClass != null)
    {
        java.lang.reflect.Field[] fields = currentClass.getDeclaredFields();
        for (java.lang.reflect.Field field : fields)
        {
            String name = field.getName();
            if ("lazyAtLoader".equals(name) || "lazyAnnotatedTypes".equals(name))
            {
                continue;
            }

            field.setAccessible(true);
            Object av = field.get(a);
            Object bv = field.get(b);

            if (av instanceof java.util.Collection && bv instanceof java.util.Collection)
            {
                java.util.List<Object> aValues = new java.util.ArrayList<Object>((java.util.Collection<?>) av);
                java.util.List<Object> bValues = new java.util.ArrayList<Object>((java.util.Collection<?>) bv);
                Assert.assertEquals("size of field " + name, aValues.size(), bValues.size());
                for (Object aValue : aValues)
                {
                    Assert.assertTrue("missing value in field " + name + ": " + aValue, bValues.remove(aValue));
                }
                Assert.assertTrue("extra values in field " + name, bValues.isEmpty());
            }
            else if (av != null && bv != null && av.getClass().isArray() && bv.getClass().isArray())
            {
                int aLength = java.lang.reflect.Array.getLength(av);
                int bLength = java.lang.reflect.Array.getLength(bv);
                Assert.assertEquals("length of field " + name, aLength, bLength);
                java.util.List<Object> aValues = new java.util.ArrayList<Object>();
                java.util.List<Object> bValues = new java.util.ArrayList<Object>();
                for (int i = 0; i < aLength; i++)
                {
                    aValues.add(java.lang.reflect.Array.get(av, i));
                    bValues.add(java.lang.reflect.Array.get(bv, i));
                }
                for (Object aValue : aValues)
                {
                    Assert.assertTrue("missing value in field " + name + ": " + aValue, bValues.remove(aValue));
                }
                Assert.assertTrue("extra values in field " + name, bValues.isEmpty());
            }
            else
            {
                Assert.assertEquals("field " + name, av, bv);
            }
        }
        currentClass = currentClass.getSuperclass();
    }

    Assert.assertEquals(a.hashCode(), b.hashCode());

    // Deterministic equals/hashCode checks using a single qualifier (order is irrelevant).
    Annotation q1 = BeanCacheKeyUnitTest.class.getDeclaredField("s1")
            .getAnnotation(AnnotationWithBindingMember.class);
    Annotation q2 = BeanCacheKeyUnitTest.class.getDeclaredField("s2")
            .getAnnotation(AnnotationWithBindingMember.class);
    Annotation q3 = BeanCacheKeyUnitTest.class.getDeclaredField("s3")
            .getAnnotation(AnnotationWithNonBindingMember.class);

    BeanCacheKey base = new BeanCacheKey(true, String.class, null, it -> null, q1);
    BeanCacheKey base2 = new BeanCacheKey(true, String.class, null, it -> null, q1);

    Assert.assertTrue(base.equals(base));
    Assert.assertFalse(base.equals(null));
    Assert.assertFalse(base.equals("not a BeanCacheKey"));
    Assert.assertEquals(base, base2);
    Assert.assertEquals(base.hashCode(), base2.hashCode());

    Assert.assertFalse(base.equals(new BeanCacheKey(false, String.class, null, it -> null, q1)));
    Assert.assertFalse(base.equals(new BeanCacheKey(true, Integer.class, null, it -> null, q1)));
    Assert.assertFalse(base.equals(new BeanCacheKey(true, String.class, "path", it -> null, q1)));
    Assert.assertFalse(base.equals(new BeanCacheKey(true, String.class, null, it -> null, q2)));
    Assert.assertFalse(base.equals(new BeanCacheKey(true, String.class, null, it -> null, q3)));
    Assert.assertFalse(base.equals(new BeanCacheKey(true, String.class, null, it -> null, q1, q2)));

    BeanCacheKey nullType1 = new BeanCacheKey(true, null, null, it -> null, q1);
    BeanCacheKey nullType2 = new BeanCacheKey(true, null, null, it -> null, q1);
    Assert.assertEquals(nullType1, nullType2);
    Assert.assertFalse(base.equals(nullType1));

    BeanCacheKey nullPath1 = new BeanCacheKey(true, String.class, null, it -> null, q1);
    BeanCacheKey nullPath2 = new BeanCacheKey(true, String.class, null, it -> null, q1);
    Assert.assertEquals(nullPath1, nullPath2);
    Assert.assertFalse(nullPath1.equals(new BeanCacheKey(true, String.class, "", it -> null, q1)));

    // Exercise and verify the lazy qualifier loading state.
    BeanCacheKey lazyKey = new BeanCacheKey(true, String.class, null, it -> null, q1);
    java.lang.reflect.Method ensure = BeanCacheKey.class.getDeclaredMethod("ensureQualifierAtAreLoaded");
    ensure.setAccessible(true);
    ensure.invoke(lazyKey);
    java.lang.reflect.Field lazyField = BeanCacheKey.class.getDeclaredField("lazyAnnotatedTypes");
    lazyField.setAccessible(true);
    Assert.assertNotNull(lazyField.get(lazyKey));

    // Exercise qualifierArrayEquals directly to cover all of its predicates.
    java.lang.reflect.Method qualifierArrayEquals = BeanCacheKey.class.getDeclaredMethod(
            "qualifierArrayEquals", Annotation[].class, Annotation[].class);
    qualifierArrayEquals.setAccessible(true);
    Assert.assertTrue((Boolean) qualifierArrayEquals.invoke(base, new Object[]{null, null}));
    Assert.assertFalse((Boolean) qualifierArrayEquals.invoke(base, new Object[]{null, new Annotation[]{q1}}));
    Assert.assertFalse((Boolean) qualifierArrayEquals.invoke(base, new Object[]{new Annotation[]{q1}, null}));
    Assert.assertTrue((Boolean) qualifierArrayEquals.invoke(base, new Object[]{new Annotation[]{q1}, new Annotation[]{q1}}));
    Assert.assertFalse((Boolean) qualifierArrayEquals.invoke(base, new Object[]{new Annotation[]{q1}, new Annotation[]{q2}}));
    Assert.assertFalse((Boolean) qualifierArrayEquals.invoke(base, new Object[]{new Annotation[]{q1}, new Annotation[]{q1, q2}}));
}
