    @Test
    public void test() throws Exception {
        // Pre-process @Cached methods to register their cache definitions before any
        // @CacheUpdate or @CacheInvalidate methods are processed. This avoids
        // order-dependent failures when reflection returns methods in an arbitrary order.
        for (Object bean : applicationContext.getBeansOfType(Object.class).values()) {
            Class<?> targetClass = AopUtils.getTargetClass(bean);
            for (Method method : targetClass.getMethods()) {
                if (AnnotatedElementUtils.findMergedAnnotation(method, Cached.class) != null) {
                    method.setAccessible(true);
                    Class<?>[] paramTypes = method.getParameterTypes();
                    Object[] args = new Object[paramTypes.length];
                    for (int i = 0; i < paramTypes.length; i++) {
                        if (paramTypes[i] == int.class) {
                            args[i] = 0;
                        } else if (paramTypes[i] == long.class) {
                            args[i] = 0L;
                        } else if (paramTypes[i] == boolean.class) {
                            args[i] = false;
                        } else if (paramTypes[i] == double.class) {
                            args[i] = 0.0;
                        } else if (paramTypes[i] == float.class) {
                            args[i] = 0.0f;
                        } else if (paramTypes[i] == short.class) {
                            args[i] = (short) 0;
                        } else if (paramTypes[i] == byte.class) {
                            args[i] = (byte) 0;
                        } else if (paramTypes[i] == char.class) {
                            args[i] = '\0';
                        } else {
                            args[i] = null;
                        }
                    }
                    try {
                        Method invocableMethod = AopUtils.selectInvocableMethod(method, bean.getClass());
                        invocableMethod.setAccessible(true);
                        invocableMethod.invoke(bean, args);
                    } catch (InvocationTargetException e) {
                        Throwable cause = e.getCause();
                        if (cause instanceof CacheConfigException) {
                            throw (CacheConfigException) cause;
                        }
                        // Ignore exceptions from the warm-up invocation; the cache
                        // definition has already been registered by the interceptor.
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
            }
        }
        doTest();
    }
