    def test_clear_responses(self):
        """ Should clear stacked WebTest responses. """
        import types

        autodoc_module = __import__('autodoc')

        def snapshot(mapping):
            saved = {}
            for key, value in mapping.items():
                if key in ('__dict__', '__weakref__', '__builtins__'):
                    continue
                if isinstance(value, list):
                    saved[key] = list(value)
                elif isinstance(value, dict):
                    saved[key] = value.copy()
                else:
                    saved[key] = value
            return saved

        def restore(target, saved, protected=()):
            for key in list(getattr(target, '__dict__', {})):
                if key not in saved and key not in protected and hasattr(target, key):
                    delattr(target, key)
            for key, value in saved.items():
                setattr(target, key, value)

        saved_module = snapshot(autodoc_module.__dict__)
        if isinstance(autodoc, types.ModuleType):
            saved_instance = None
            saved_class = None
            autodoc_cls = None
        else:
            saved_instance = snapshot(autodoc.__dict__)
            autodoc_cls = type(autodoc)
            saved_class = snapshot(autodoc_cls.__dict__)

        try:
            res = self.client.get('/')
            autodoc.parse('GET /', res)
            autodoc.parse('GET /', res)
            autodoc.clear()
            self.assertEqual(autodoc.vars, [])
        finally:
            if saved_instance is not None:
                restore(autodoc, saved_instance)
                restore(autodoc_cls, saved_class, ('__dict__', '__weakref__'))
            restore(autodoc_module, saved_module, ('__builtins__',))
