//<fix start>
    @Test
    public void testSimpleReflectionStatics() {
        final java.util.function.Function<String, String> normalizeFieldOrder = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start < 0 || end < start) {
                return s;
            }
            final String[] fields = s.substring(start + 1, end).split(",");
            java.util.Arrays.sort(fields);
            final StringBuilder sb = new StringBuilder(s.length());
            sb.append(s, 0, start + 1);
            for (int i = 0; i < fields.length; i++) {
                if (i > 0) {
                    sb.append(',');
                }
                sb.append(fields[i]);
            }
            sb.append(s, end, s.length());
            return sb.toString();
        };

        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expected = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
        assertEquals(
            normalizeFieldOrder.apply(expected),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expected),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expected),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expected),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));

        final String expectedNoStatics = this.toBaseString(instance1) + "[]";
        assertEquals(
            normalizeFieldOrder.apply(expectedNoStatics),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, false, SimpleReflectionStaticFieldsFixture.class)));

        class SpecialFieldsFixture {
            public String normal = "normal";
            public transient String transientField = "transient";
            public String dollar$Field = "dollar";
        }
        final SpecialFieldsFixture special = new SpecialFieldsFixture();
        final String specialExpected = this.toBaseString(special) + "[normal=normal]";
        assertEquals(
            normalizeFieldOrder.apply(specialExpected),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(special, null, false, true, SpecialFieldsFixture.class)));
    }
