    @Test
    public void testSimpleReflectionStatics() {
        final java.util.function.Function<String, String> normalizeFieldOrder = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start < 0 || end < start) {
                return s;
            }
            final String[] fields = s.substring(start + 1, end).split(",");
            java.util.Arrays.sort(fields);
            final StringBuilder sb = new StringBuilder(s.length());
            sb.append(s, 0, start + 1);
            for (int i = 0; i < fields.length; i++) {
                if (i > 0) {
                    sb.append(',');
                }
                sb.append(fields[i]);
            }
            sb.append(s, end, s.length());
            return sb.toString();
        };

        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expectedStatics = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
        assertEquals(
            normalizeFieldOrder.apply(expectedStatics),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expectedStatics),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expectedStatics),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expectedStatics),
            normalizeFieldOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));

        final String expectedNoStatics = this.toBaseString(instance1) + "[]";
        assertEquals(
            normalizeFieldOrder.apply(expectedNoStatics),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, false, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(expectedNoStatics),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(instance1, null, true, false, SimpleReflectionStaticFieldsFixture.class)));

        class AllFieldsFixture {
            public String normal = "normal";
            public transient String transientField = "transient";
            public String dollar$Field = "dollar";
            public static final String STATIC = "static";
        }
        final AllFieldsFixture all = new AllFieldsFixture();
        final String allBase = this.toBaseString(all);
        assertEquals(
            normalizeFieldOrder.apply(allBase + "[normal=normal]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(all, null, false, false, AllFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(allBase + "[normal=normal,transientField=transient]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(all, null, true, false, AllFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(allBase + "[normal=normal,STATIC=static]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(all, null, false, true, AllFieldsFixture.class)));
        assertEquals(
            normalizeFieldOrder.apply(allBase + "[normal=normal,transientField=transient,STATIC=static]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(all, null, true, true, AllFieldsFixture.class)));

        class ParentFixture {
            public String parent = "parent";
        }
        class ChildFixture extends ParentFixture {
            public String child = "child";
        }
        final ChildFixture child = new ChildFixture();
        assertEquals(
            normalizeFieldOrder.apply(this.toBaseString(child) + "[child=child]"),
            normalizeFieldOrder.apply(ReflectionToStringBuilder.toString(child, null, false, false, ChildFixture.class)));
    }
