    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String actual = toString(wa);
        final String prefix = getClassPrefix(wa) + "[" + BR;
        final String suffix = BR + "]";

        assertEquals(prefix, actual.substring(0, prefix.length()), actual);
        assertEquals(suffix, actual.substring(actual.length() - suffix.length()), actual);

        final String body = actual.substring(prefix.length(), actual.length() - suffix.length());
        final String[] lines = body.split(java.util.regex.Pattern.quote(BR), -1);
        final java.util.Map<String, String> actualBlocks = new java.util.LinkedHashMap<>();
        String currentName = null;
        StringBuilder currentBlock = null;
        for (final String line : lines) {
            final int eq = line.indexOf('=');
            if (line.startsWith("  ") && !line.startsWith("    ") && eq >= 0) {
                if (currentName != null) {
                    actualBlocks.put(currentName, currentBlock.toString());
                }
                currentName = line.substring(2, eq).trim();
                currentBlock = new StringBuilder(line);
            } else {
                currentBlock.append(BR).append(line);
            }
        }
        if (currentName != null) {
            actualBlocks.put(currentName, currentBlock.toString());
        }

        final java.util.Map<String, String> actualFields = new java.util.LinkedHashMap<>();
        int fieldIndex = 0;
        for (final java.util.Map.Entry<String, String> entry : actualBlocks.entrySet()) {
            String block = entry.getValue();
            final boolean hasSeparatorComma = block.endsWith(",");
            assertEquals(fieldIndex < actualBlocks.size() - 1, hasSeparatorComma, actual);
            if (hasSeparatorComma) {
                block = block.substring(0, block.length() - 1);
            }
            actualFields.put(entry.getKey(), block);
            fieldIndex++;
        }

        final java.util.Map<String, String> expectedFields = new java.util.LinkedHashMap<>();
        expectedFields.put("boolArray", "  boolArray=<null>");
        expectedFields.put("charArray", "  charArray=<null>");
        expectedFields.put("intArray", "  intArray=<null>");
        expectedFields.put("doubleArray", "  doubleArray={" + BR
                + "    1.0," + BR
                + "    2.0" + BR
                + "  }");
        expectedFields.put("longArray", "  longArray=<null>");
        expectedFields.put("stringArray", "  stringArray=<null>");

        assertEquals(expectedFields, actualFields, actual);
    }
