    @Test
    public void testSimpleReflectionStatics() {
        final java.util.function.Function<String, String> basePart = s -> {
            final int start = s.indexOf('[');
            return start < 0 ? s : s.substring(0, start);
        };
        final java.util.function.Function<String, java.util.Map<String, String>> fieldMap = s -> {
            final java.util.Map<String, String> fields = new java.util.HashMap<>();
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start >= 0 && end > start + 1) {
                for (final String pair : s.substring(start + 1, end).split(",")) {
                    final int equals = pair.indexOf('=');
                    if (equals >= 0) {
                        fields.put(pair.substring(0, equals), pair.substring(equals + 1));
                    } else {
                        fields.put(pair, "");
                    }
                }
            }
            return fields;
        };
        final java.util.function.BiConsumer<String, String> assertReflection = (expected, actual) -> {
            assertEquals(basePart.apply(expected), basePart.apply(actual));
            assertEquals(fieldMap.apply(expected), fieldMap.apply(actual));
        };

        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String expectedStatics = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
        assertReflection.accept(
            expectedStatics,
            ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class));
        assertReflection.accept(
            expectedStatics,
            ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class));
        assertReflection.accept(
            expectedStatics,
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
        assertReflection.accept(
            expectedStatics,
            this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));

        final String expectedNoStatics = this.toBaseString(instance1) + "[]";
        assertReflection.accept(
            expectedNoStatics,
            ReflectionToStringBuilder.toString(instance1, null, false, false, SimpleReflectionStaticFieldsFixture.class));
        assertReflection.accept(
            expectedNoStatics,
            ReflectionToStringBuilder.toString(instance1, null, true, false, SimpleReflectionStaticFieldsFixture.class));

        class AllFieldsFixture {
            public String normal = "normal";
            public transient String transientField = "transient";
            public String dollar$Field = "dollar";
            public static final String STATIC = "static";
        }
        final AllFieldsFixture all = new AllFieldsFixture();
        final String allBase = this.toBaseString(all);
        assertReflection.accept(
            allBase + "[normal=normal]",
            ReflectionToStringBuilder.toString(all, null, false, false, AllFieldsFixture.class));
        assertReflection.accept(
            allBase + "[normal=normal,transientField=transient]",
            ReflectionToStringBuilder.toString(all, null, true, false, AllFieldsFixture.class));
        assertReflection.accept(
            allBase + "[normal=normal,STATIC=static]",
            ReflectionToStringBuilder.toString(all, null, false, true, AllFieldsFixture.class));
        assertReflection.accept(
            allBase + "[normal=normal,transientField=transient,STATIC=static]",
            ReflectionToStringBuilder.toString(all, null, true, true, AllFieldsFixture.class));

        class ParentFixture {
            public String parent = "parent";
        }
        class ChildFixture extends ParentFixture {
            public String child = "child";
        }
        final ChildFixture child = new ChildFixture();
        final String childBase = this.toBaseString(child);
        assertReflection.accept(
            childBase + "[child=child]",
            ReflectionToStringBuilder.toString(child, null, false, false, ChildFixture.class));
        assertReflection.accept(
            childBase + "[child=child,parent=parent]",
            ReflectionToStringBuilder.toString(child, null, false, false, ParentFixture.class));

        class ExcludeFixture {
            public String kept = "kept";
            public String excluded = "excluded";
        }
        final ExcludeFixture excludeFixture = new ExcludeFixture();
        final ReflectionToStringBuilder excludeBuilder = new ReflectionToStringBuilder(
            excludeFixture, null, null, ExcludeFixture.class, false, false);
        excludeBuilder.setExcludeFieldNames("excluded");
        assertReflection.accept(
            this.toBaseString(excludeFixture) + "[kept=kept]",
            excludeBuilder.toString());
    }
