    @Test
    public void testReflectionStatics() throws Exception {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();

        final java.util.function.Function<String, String> canonicalize = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            assertEquals(s.length() - 1, end);
            final String prefix = s.substring(0, start);
            final String fieldBody = s.substring(start + 1, end);
            final List<String> fields = new ArrayList<>();
            if (!fieldBody.isEmpty()) {
                fields.addAll(java.util.Arrays.asList(fieldBody.split(",")));
            }
            java.util.Collections.sort(fields);
            return prefix + "[" + String.join(",", fields) + "]";
        };

        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]"),
            canonicalize.apply(ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));

        final ReflectionToStringBuilder builderTransientsFalseStaticsTrue =
            new ReflectionToStringBuilder(instance1, null, null, ReflectionStaticFieldsFixture.class, false, true);
        final ReflectionToStringBuilder builderTransientsTrueStaticsTrue =
            new ReflectionToStringBuilder(instance1, null, null, ReflectionStaticFieldsFixture.class, true, true);
        final ReflectionToStringBuilder builderTransientsTrueStaticsFalse =
            new ReflectionToStringBuilder(instance1, null, null, ReflectionStaticFieldsFixture.class, true, false);

        assertEquals(ReflectionStaticFieldsFixture.class, builderTransientsFalseStaticsTrue.getUpToClass());
        assertEquals(Boolean.FALSE, builderTransientsFalseStaticsTrue.isAppendTransients());
        assertEquals(Boolean.TRUE, builderTransientsFalseStaticsTrue.isAppendStatics());
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.isAppendTransients());
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.isAppendStatics());

        final java.lang.reflect.Field staticString = ReflectionStaticFieldsFixture.class.getDeclaredField("staticString");
        final java.lang.reflect.Field staticInt = ReflectionStaticFieldsFixture.class.getDeclaredField("staticInt");
        final java.lang.reflect.Field staticTransientString = ReflectionStaticFieldsFixture.class.getDeclaredField("staticTransientString");
        final java.lang.reflect.Field staticTransientInt = ReflectionStaticFieldsFixture.class.getDeclaredField("staticTransientInt");
        final java.lang.reflect.Field instanceString = ReflectionStaticFieldsFixture.class.getDeclaredField("instanceString");
        final java.lang.reflect.Field instanceInt = ReflectionStaticFieldsFixture.class.getDeclaredField("instanceInt");
        final java.lang.reflect.Field transientString = ReflectionStaticFieldsFixture.class.getDeclaredField("transientString");
        final java.lang.reflect.Field transientInt = ReflectionStaticFieldsFixture.class.getDeclaredField("transientInt");

        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(staticString));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(staticInt));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(staticTransientString));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(staticTransientInt));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(instanceString));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(instanceInt));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(transientString));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsTrue.accept(transientInt));

        assertEquals(Boolean.FALSE, builderTransientsFalseStaticsTrue.accept(staticTransientString));
        assertEquals(Boolean.FALSE, builderTransientsFalseStaticsTrue.accept(staticTransientInt));
        assertEquals(Boolean.FALSE, builderTransientsFalseStaticsTrue.accept(transientString));
        assertEquals(Boolean.FALSE, builderTransientsFalseStaticsTrue.accept(transientInt));
        assertEquals(Boolean.TRUE, builderTransientsFalseStaticsTrue.accept(staticString));
        assertEquals(Boolean.TRUE, builderTransientsFalseStaticsTrue.accept(instanceString));

        assertEquals(Boolean.FALSE, builderTransientsTrueStaticsFalse.accept(staticString));
        assertEquals(Boolean.FALSE, builderTransientsTrueStaticsFalse.accept(staticInt));
        assertEquals(Boolean.FALSE, builderTransientsTrueStaticsFalse.accept(staticTransientString));
        assertEquals(Boolean.FALSE, builderTransientsTrueStaticsFalse.accept(staticTransientInt));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsFalse.accept(instanceString));
        assertEquals(Boolean.TRUE, builderTransientsTrueStaticsFalse.accept(transientString));

        class DollarFieldFixture {
            @SuppressWarnings("unused")
            String $dollar = "dollar";
        }
        final java.lang.reflect.Field dollarField = DollarFieldFixture.class.getDeclaredField("$dollar");
        assertEquals(Boolean.FALSE, builderTransientsTrueStaticsTrue.accept(dollarField));
    }
