    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        final java.util.function.Function<String, List<String>> toSortedParts = value -> {
            final List<String> parts = new ArrayList<>();
            final int start = value.indexOf('[');
            final int end = value.lastIndexOf(']');
            parts.add(value.substring(0, start));
            final String contents = value.substring(start + 1, end);
            if (!contents.isEmpty()) {
                for (final String field : contents.split(",")) {
                    parts.add(field);
                }
            }
            java.util.Collections.sort(parts);
            return parts;
        };

        final String expectedPrefix = this.toBaseString(instance1);

        final List<String> expected1 = new ArrayList<>();
        expected1.add(expectedPrefix);
        expected1.add("staticString2=staticString2");
        expected1.add("staticInt2=67890");
        java.util.Collections.sort(expected1);

        assertEquals(
            expected1,
