@Test
public void testSimpleReflectionStatics() {
    final java.util.function.Function<String, String> basePart = s -> {
        final int start = s.indexOf('[');
        return start < 0 ? s : s.substring(0, start);
    };
    final java.util.function.Function<String, java.util.List<String>> fieldList = s -> {
        final java.util.List<String> fields = new java.util.ArrayList<>();
        final int start = s.indexOf('[');
        final int end = s.lastIndexOf(']');
        if (start >= 0 && end > start + 1) {
            final String body = s.substring(start + 1, end);
            if (!body.isEmpty()) {
                for (final String pair : body.split(",")) {
                    fields.add(pair);
                }
            }
        }
        java.util.Collections.sort(fields);
        return fields;
    };
    final java.util.function.BiConsumer<String, String> assertReflection = (expected, actual) -> {
        assertEquals(basePart.apply(expected), basePart.apply(actual));
        assertEquals(fieldList.apply(expected), fieldList.apply(actual));
    };

    final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
    final String expectedStatics = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345]";
    assertReflection.accept(
        expectedStatics,
        ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class));
    assertReflection.accept(
        expectedStatics,
        ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class));
    assertReflection.accept(
        expectedStatics,
        this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));
    assertReflection.accept(
        expectedStatics,
        this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class));

    final String expectedNoStatics = this.toBaseString(instance1) + "[]";
    assertReflection.accept(
        expectedNoStatics,
