            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));
        assertEquals(
            canonicalize.apply(this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]"),
            canonicalize.apply(this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class)));

        final ReflectionToStringBuilder flagsTrue = new ReflectionToStringBuilder(
                instance1, null, null, ReflectionStaticFieldsFixture.class, true, true);
        assertEquals(true, flagsTrue.isAppendTransients());
        assertEquals(true, flagsTrue.isAppendStatics());

        final ReflectionToStringBuilder flagsFalse = new ReflectionToStringBuilder(
                instance1, null, null, ReflectionStaticFieldsFixture.class, false, false);
        assertEquals(false, flagsFalse.isAppendTransients());
        assertEquals(false, flagsFalse.isAppendStatics());

        final java.lang.reflect.Field staticString =
                ReflectionStaticFieldsFixture.class.getDeclaredField("staticString");
        final java.lang.reflect.Field staticTransientString =
                ReflectionStaticFieldsFixture.class.getDeclaredField("staticTransientString");
        final java.lang.reflect.Field instanceString =
                ReflectionStaticFieldsFixture.class.getDeclaredField("instanceString");
        final java.lang.reflect.Field transientString =
                ReflectionStaticFieldsFixture.class.getDeclaredField("transientString");

        final ReflectionToStringBuilder acceptBuilder = new ReflectionToStringBuilder(
                instance1, null, null, ReflectionStaticFieldsFixture.class, false, false);
        assertEquals(false, acceptBuilder.accept(staticString));
        assertEquals(false, acceptBuilder.accept(staticTransientString));
        assertEquals(false, acceptBuilder.accept(transientString));
