    @Test
    public void testEquals2Annotations()
    {
        class BindingAnnotationHandler implements java.lang.reflect.InvocationHandler
        {
            private final String value;
            private final int number;

            BindingAnnotationHandler(String value, int number)
            {
                this.value = value;
                this.number = number;
            }

            @Override
            public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args) throws Throwable
            {
                String name = method.getName();
                if ("annotationType".equals(name))
                {
                    return AnnotationWithBindingMember.class;
                }
                if ("value".equals(name))
                {
                    return value;
                }
                if ("number".equals(name))
                {
                    return number;
                }
                if ("toString".equals(name))
                {
                    return "@" + AnnotationWithBindingMember.class.getName()
                        + "(number=" + number + ", value=" + value + ")";
                }
                if ("hashCode".equals(name))
                {
                    return (127 * "value".hashCode() ^ value.hashCode())
                        + (127 * "number".hashCode() ^ Integer.valueOf(number).hashCode());
                }
                if ("equals".equals(name))
                {
                    if (args == null || args.length == 0 || !(args[0] instanceof AnnotationWithBindingMember))
                    {
                        return false;
                    }
                    AnnotationWithBindingMember other = (AnnotationWithBindingMember) args[0];
                    return number == other.number() && value.equals(other.value());
                }
                throw new UnsupportedOperationException(name);
            }
        }

        Annotation q0 = (Annotation) java.lang.reflect.Proxy.newProxyInstance(
            AnnotationWithBindingMember.class.getClassLoader(),
            new Class<?>[] { AnnotationWithBindingMember.class },
            new BindingAnnotationHandler("B", 0));
        Annotation q1 = (Annotation) java.lang.reflect.Proxy.newProxyInstance(
            AnnotationWithBindingMember.class.getClassLoader(),
            new Class<?>[] { AnnotationWithBindingMember.class },
            new BindingAnnotationHandler("B", 1));
        Annotation q3 = (Annotation) java.lang.reflect.Proxy.newProxyInstance(
            AnnotationWithBindingMember.class.getClassLoader(),
            new Class<?>[] { AnnotationWithBindingMember.class },
            new BindingAnnotationHandler("B", 3));
        Annotation q4 = (Annotation) java.lang.reflect.Proxy.newProxyInstance(
            AnnotationWithBindingMember.class.getClassLoader(),
            new Class<?>[] { AnnotationWithBindingMember.class },
            new BindingAnnotationHandler("B", 4));

        Annotation[] qualifiers = new Annotation[] { q3, q0 };
        Annotation[] reversedQualifiers = new Annotation[] { q0, q3 };

        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, qualifiers);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, qualifiers);
        BeanCacheKey c = new BeanCacheKey(true, String.class, null, it -> null, reversedQualifiers);
        BeanCacheKey d = new BeanCacheKey(true, String.class, null, it -> null, new Annotation[] { q0, q4 });
        BeanCacheKey e = new BeanCacheKey(true, String.class, null, it -> null, new Annotation[] { q1, q3 });

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());

        Assert.assertEquals(a, c);
        Assert.assertEquals(a.hashCode(), c.hashCode());

        Assert.assertFalse(a.equals(d));
        Assert.assertFalse(a.hashCode() == d.hashCode());

        Assert.assertFalse(a.equals(e));
        Assert.assertFalse(a.hashCode() == e.hashCode());
    }
