    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        List<String> actualIfColumns = new ArrayList<String>();
        StringBuffer actualSkeleton = new StringBuffer();
        Matcher actualMatcher = Pattern.compile("<if\\b.*?</if>", Pattern.DOTALL).matcher(whereAllIfColumns);
        while (actualMatcher.find()) {
            actualIfColumns.add(actualMatcher.group());
            actualMatcher.appendReplacement(actualSkeleton, "");
        }
        actualMatcher.appendTail(actualSkeleton);

        List<String> expectedIfColumns = new ArrayList<String>();
        StringBuffer expectedSkeleton = new StringBuffer();
        Matcher expectedMatcher = Pattern.compile("<if\\b.*?</if>", Pattern.DOTALL).matcher(expectedWhereAllIfColumns);
        while (expectedMatcher.find()) {
            expectedIfColumns.add(expectedMatcher.group());
            expectedMatcher.appendReplacement(expectedSkeleton, "");
        }
        expectedMatcher.appendTail(expectedSkeleton);

        Collections.sort(actualIfColumns);
        Collections.sort(expectedIfColumns);
        Assert.assertEquals(expectedSkeleton.toString(), actualSkeleton.toString());
        Assert.assertEquals(expectedIfColumns, actualIfColumns);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertEquals("<set>username = #{username},is_valid = 1,</set>", updateSetColumns);
    }
