    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        Pattern ifPattern = Pattern.compile("<if\\b.*?</if>", Pattern.DOTALL);

        Matcher expectedMatcher = ifPattern.matcher(expectedWhereAllIfColumns);
        List<String> expectedIfColumns = new ArrayList<String>();
        while (expectedMatcher.find()) {
            expectedIfColumns.add(expectedMatcher.group());
        }

        Matcher actualMatcher = ifPattern.matcher(whereAllIfColumns);
        List<String> actualIfColumns = new ArrayList<String>();
        while (actualMatcher.find()) {
            actualIfColumns.add(actualMatcher.group());
        }

        int expectedFirstIf = expectedWhereAllIfColumns.indexOf("<if");
        int expectedLastIfEnd = expectedWhereAllIfColumns.lastIndexOf("</if>") + "</if>".length();
        int actualFirstIf = whereAllIfColumns.indexOf("<if");
        int actualLastIfEnd = whereAllIfColumns.lastIndexOf("</if>") + "</if>".length();

        Assert.assertEquals(
                expectedWhereAllIfColumns.substring(0, expectedFirstIf),
                whereAllIfColumns.substring(0, actualFirstIf));
        Assert.assertEquals(
                expectedWhereAllIfColumns.substring(expectedLastIfEnd),
                whereAllIfColumns.substring(actualLastIfEnd));
        Assert.assertEquals("", ifPattern.matcher(
                expectedWhereAllIfColumns.substring(expectedFirstIf, expectedLastIfEnd)).replaceAll(""));
        Assert.assertEquals("", ifPattern.matcher(
                whereAllIfColumns.substring(actualFirstIf, actualLastIfEnd)).replaceAll(""));

        Collections.sort(expectedIfColumns);
        Collections.sort(actualIfColumns);
        Assert.assertEquals(expectedIfColumns, actualIfColumns);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSetColumns = "<set>username = #{username},is_valid = 1,</set>";
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));

        String expectedUpdateSetBody = expectedUpdateSetColumns.substring(
                "<set>".length(), expectedUpdateSetColumns.length() - "</set>".length());
        String actualUpdateSetBody = updateSetColumns.substring(
                "<set>".length(), updateSetColumns.length() - "</set>".length());

        List<String> expectedUpdateSetParts = new ArrayList<String>();
        Collections.addAll(expectedUpdateSetParts, expectedUpdateSetBody.split(",", -1));
        List<String> actualUpdateSetParts = new ArrayList<String>();
        Collections.addAll(actualUpdateSetParts, actualUpdateSetBody.split(",", -1));

        Collections.sort(expectedUpdateSetParts);
        Collections.sort(actualUpdateSetParts);
        Assert.assertEquals(expectedUpdateSetParts, actualUpdateSetParts);
    }
