//<fix start>
    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        class Normalizer
        {
            Object normalize(Object value)
            {
                if (value == null)
                {
                    return null;
                }
                if (value.getClass().isArray())
                {
                    int length = java.lang.reflect.Array.getLength(value);
                    java.util.List<Object> list = new java.util.ArrayList<Object>();
                    for (int i = 0; i < length; i++)
                    {
                        list.add(normalize(java.lang.reflect.Array.get(value, i)));
                    }
                    java.util.Collections.sort(list, new java.util.Comparator<Object>()
                    {
                        public int compare(Object o1, Object o2)
                        {
                            return String.valueOf(o1).compareTo(String.valueOf(o2));
                        }
                    });
                    return list;
                }
                if (value instanceof java.util.Collection)
                {
                    java.util.List<Object> list = new java.util.ArrayList<Object>();
                    for (Object element : (java.util.Collection<?>) value)
                    {
                        list.add(normalize(element));
                    }
                    java.util.Collections.sort(list, new java.util.Comparator<Object>()
                    {
                        public int compare(Object o1, Object o2)
                        {
                            return String.valueOf(o1).compareTo(String.valueOf(o2));
                        }
                    });
                    return list;
                }
                if (value instanceof java.util.Map)
                {
                    java.util.Map<String, Object> map = new java.util.TreeMap<String, Object>();
                    for (java.util.Map.Entry<?, ?> entry : ((java.util.Map<?, ?>) value).entrySet())
                    {
                        map.put(String.valueOf(normalize(entry.getKey())), normalize(entry.getValue()));
                    }
                    return map;
                }
                return value.toString();
            }

            java.util.Map<String, Object> normalizeBean(Object bean) throws Exception
            {
                java.util.Map<String, Object> result = new java.util.TreeMap<String, Object>();
                Class<?> clazz = bean.getClass();
                while (clazz != null && clazz != Object.class)
                {
                    for (java.lang.reflect.Field field : clazz.getDeclaredFields())
                    {
                        if (java.lang.reflect.Modifier.isStatic(field.getModifiers()) || field.isSynthetic())
                        {
                            continue;
                        }
                        field.setAccessible(true);
                        result.put(clazz.getName() + "#" + field.getName(), normalize(field.get(bean)));
                    }
                    clazz = clazz.getSuperclass();
                }
                return result;
            }
        }

        Normalizer normalizer = new Normalizer();
        Assert.assertEquals(normalizer.normalizeBean(a), normalizer.normalizeBean(b));
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
