//<polluter start>
    @Test(expected=Error.class)
    public void testDefaultsAreUsedIfOverridesAreGarbage() throws Exception {
        List<String> badClasses = Collections.singletonList("Z{100,0}" /* min > max for repetition */);
        File f = folder.newFile("overrides.txt");
        try (FileOutputStream fos = new FileOutputStream(f)) {
            for (String s : badClasses) {
                IOUtils.write(s, fos);
                IOUtils.write("\n", fos);
            }
        }
        setOverrideProperty(f.getAbsolutePath());
        try {
            // Initialize a fresh copy of ClassFilter so a failed class initialization
            // cannot poison the ClassFilter class used by subsequent tests.
            ClassLoader isolated = new ClassLoader(DefaultClassFilterTest.class.getClassLoader()) {
                @Override
                protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
                    if (name.equals("hudson.remoting.ClassFilter")
                            || name.startsWith("hudson.remoting.ClassFilter$")) {
                        synchronized (getClassLoadingLock(name)) {
                            Class<?> c = findLoadedClass(name);
                            if (c == null) {
                                try (java.io.InputStream in = getParent().getResourceAsStream(name.replace('.', '/') + ".class")) {
                                    if (in == null) {
                                        throw new ClassNotFoundException(name);
                                    }
                                    byte[] bytes = IOUtils.toByteArray(in);
                                    c = defineClass(name, bytes, 0, bytes.length);
                                } catch (java.io.IOException e) {
                                    throw new ClassNotFoundException(name, e);
                                }
                            }
                            if (resolve) {
                                resolveClass(c);
                            }
                            return c;
                        }
                    }
