public void test_list() throws Exception {
    Model model = new Model();
    Map tables = new LinkedHashMap();
    tables.put("1001", new ExtTable(1001));
    tables.put("1002", new Table());
    model.setTables(tables);

    String json = JSON.toJSONString(model);
    assertEquals("{\"tables\":{\"1001\":{\"@type\":\"com.alibaba.json.bvt.writeClassName.WriteClassNameTest_Map$ExtTable\",\"id\":1001},\"1002\":{}}}", json);

    JSONObject jsonObject = JSON.parseObject(json, Feature.IgnoreAutoType);

    String expectedJson = "{\"tables\":{\"1002\":{},\"1001\":{\"id\":1001}}}";
    JSONObject expectedJsonObject = JSON.parseObject(expectedJson);
    assertEquals(expectedJsonObject, jsonObject);

    String actualJson = jsonObject.toJSONString();

    class JsonCanonicalizer {
        private String s;
        private int i;

        String canonical(String text) {
            this.s = text;
            this.i = 0;
            String result = parseValue();
            skipWhitespace();
            if (i != s.length()) {
                throw new IllegalArgumentException("trailing characters: " + s.substring(i));
            }
            return result;
        }

        boolean hasWhitespaceOutsideString(String text) {
            boolean inString = false;
            boolean escaped = false;
            for (int p = 0; p < text.length(); p++) {
                char c = text.charAt(p);
                if (inString) {
                    if (escaped) {
                        escaped = false;
                    } else if (c == '\\') {
                        escaped = true;
                    } else if (c == '"') {
                        inString = false;
                    }
                } else {
                    if (c == '"') {
                        inString = true;
                    } else if (Character.isWhitespace(c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private String parseValue() {
            skipWhitespace();
            char c = s.charAt(i);
            if (c == '{') {
                return parseObject();
            } else if (c == '[') {
                return parseArray();
            } else if (c == '"') {
                return parseString();
            } else {
                int start = i;
                while (i < s.length()) {
                    c = s.charAt(i);
                    if (c == ',' || c == '}' || c == ']' || Character.isWhitespace(c)) {
                        break;
                    }
                    i++;
                }
                if (start == i) {
                    throw new IllegalArgumentException("empty value");
                }
                return s.substring(start, i);
            }
        }

        private String parseObject() {
            i++;
            List<String[]> entries = new ArrayList<String[]>();
            skipWhitespace();
            if (s.charAt(i) == '}') {
                i++;
                return "{}";
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                if (s.charAt(i) != ':') {
                    throw new IllegalArgumentException("expected :");
                }
                i++;
                String value = parseValue();
                entries.add(new String[] {key, value});
                skipWhitespace();
                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == '}') {
                    i++;
                    break;
                }
                throw new IllegalArgumentException("expected , or }");
            }
            Collections.sort(entries, new Comparator<String[]>() {
                public int compare(String[] a, String[] b) {
                    return a[0].compareTo(b[0]);
                }
            });
            StringBuilder buf = new StringBuilder();
            buf.append('{');
            for (int j = 0; j < entries.size(); j++) {
                if (j != 0) {
                    buf.append(',');
                }
                String[] entry = entries.get(j);
                buf.append(entry[0]).append(':').append(entry[1]);
            }
            buf.append('}');
            return buf.toString();
        }

        private String parseArray() {
            i++;
            List<String> values = new ArrayList<String>();
            skipWhitespace();
            if (s.charAt(i) == ']') {
                i++;
                return "[]";
            }
            while (true) {
                values.add(parseValue());
                skipWhitespace();
                char c = s.charAt(i);
                if (c == ',') {
                    i++;
                    continue;
                }
                if (c == ']') {
                    i++;
                    break;
                }
                throw new IllegalArgumentException("expected , or ]");
            }
            StringBuilder buf = new StringBuilder();
            buf.append('[');
            for (int j = 0; j < values.size(); j++) {
                if (j != 0) {
                    buf.append(',');
                }
                buf.append(values.get(j));
            }
            buf.append(']');
            return buf.toString();
        }

        private String parseString() {
            int start = i;
            i++;
            while (i < s.length()) {
                char c = s.charAt(i++);
                if (c == '\\') {
                    if (i < s.length()) {
                        i++;
                    }
                } else if (c == '"') {
                    return s.substring(start, i);
                }
            }
            throw new IllegalArgumentException("unterminated string");
        }

        private void skipWhitespace() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) {
                i++;
            }
        }
    }

    JsonCanonicalizer canonicalizer = new JsonCanonicalizer();
    assertFalse(canonicalizer.hasWhitespaceOutsideString(actualJson));
    assertEquals(canonicalizer.canonical(expectedJson), canonicalizer.canonical(actualJson));

    Model model2 = JSON.parseObject(json, Model.class);
    assertEquals(ExtTable.class, model2.getTables().get("1001").getClass());
}
