    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String exp = getClassPrefix(wa) + "[" + BR
                   + "  boolArray=<null>," + BR
                   + "  charArray=<null>," + BR
                   + "  intArray=<null>," + BR
                   + "  doubleArray={" + BR
                   + "    1.0," + BR
                   + "    2.0" + BR
                   + "  }," + BR
                   + "  longArray=<null>," + BR
                   + "  stringArray=<null>" + BR
                   + "]";
        final String actual = toString(wa);

        final java.util.function.Function<String[], java.util.Map<String, String>> parseFields = lines -> {
            final java.util.Map<String, String> fields = new java.util.HashMap<>();
            String fieldName = null;
            StringBuilder block = null;

            for (int i = 1; i < lines.length; i++) {
                final String line = lines[i];
                if ("]".equals(line)) {
                    if (fieldName != null) {
                        String value = block.toString();
                        if (value.endsWith(",")) {
                            value = value.substring(0, value.length() - 1);
                        }
                        fields.put(fieldName, value);
                    }
                    break;
                }

                final int eq = line.indexOf('=');
                final boolean startsField = line.startsWith("  ")
                        && !line.startsWith("   ")
                        && eq > 2;

                if (startsField) {
                    if (fieldName != null) {
                        String value = block.toString();
                        if (value.endsWith(",")) {
                            value = value.substring(0, value.length() - 1);
                        }
                        fields.put(fieldName, value);
                    }
                    fieldName = line.substring(2, eq);
                    block = new StringBuilder(line);
                } else {
                    if (block == null) {
                        throw new IllegalArgumentException("Unexpected line: " + line);
                    }
                    block.append(BR).append(line);
                }
            }

            return fields;
        };

        final String[] expLines = exp.split(java.util.regex.Pattern.quote(BR), -1);
        final String[] actualLines = actual.split(java.util.regex.Pattern.quote(BR), -1);

        assertEquals(expLines[0], actualLines[0]);

        final java.util.Map<String, String> expFields = parseFields.apply(expLines);
        final java.util.Map<String, String> actualFields = parseFields.apply(actualLines);

        assertEquals(expFields, actualFields);
    }
