    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        boolean foundId = false;
        boolean foundUsername = false;
        for (tk.mybatis.mapper.entity.EntityColumn column : EntityHelper.getColumns(User.class)) {
            if ("id".equals(column.getProperty())) {
                foundId = true;
                Assert.assertEquals("id", column.getColumn());
                Assert.assertEquals("id = #{id}", column.getColumnEqualsHolder());
                Assert.assertEquals("id = #{id}", column.getColumnEqualsHolder(null));
                Assert.assertEquals("#{id}", column.getColumnHolder());
                Assert.assertEquals("#{id}", column.getColumnHolder(null));
                Assert.assertEquals("#{id}", column.getColumnHolder(null, null));
            } else if ("username".equals(column.getProperty())) {
                foundUsername = true;
                Assert.assertEquals("username", column.getColumn());
                Assert.assertEquals("username = #{username}", column.getColumnEqualsHolder());
                Assert.assertEquals("username = #{username}", column.getColumnEqualsHolder(null));
                Assert.assertEquals("#{username}", column.getColumnHolder());
                Assert.assertEquals("#{username}", column.getColumnHolder(null));
                Assert.assertEquals("#{username}", column.getColumnHolder(null, null));
            }
        }
        Assert.assertTrue(foundId);
        Assert.assertTrue(foundUsername);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";

        List<String> actualIfColumns = new ArrayList<String>();
        StringBuffer actualSkeleton = new StringBuffer();
        Matcher actualMatcher = Pattern.compile("<if\\b.*?</if>", Pattern.DOTALL).matcher(whereAllIfColumns);
        while (actualMatcher.find()) {
            actualIfColumns.add(actualMatcher.group());
            actualMatcher.appendReplacement(actualSkeleton, "");
        }
        actualMatcher.appendTail(actualSkeleton);

        List<String> expectedIfColumns = new ArrayList<String>();
        StringBuffer expectedSkeleton = new StringBuffer();
        Matcher expectedMatcher = Pattern.compile("<if\\b.*?</if>", Pattern.DOTALL).matcher(expectedWhereAllIfColumns);
        while (expectedMatcher.find()) {
            expectedIfColumns.add(expectedMatcher.group());
            expectedMatcher.appendReplacement(expectedSkeleton, "");
        }
        expectedMatcher.appendTail(expectedSkeleton);

        Collections.sort(actualIfColumns);
        Collections.sort(expectedIfColumns);
        Assert.assertEquals(expectedSkeleton.toString(), actualSkeleton.toString());
        Assert.assertEquals(expectedIfColumns, actualIfColumns);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        String expectedUpdateSetColumns = "<set>username = #{username},is_valid = 1,</set>";
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));
        Assert.assertTrue(expectedUpdateSetColumns.startsWith("<set>"));
        Assert.assertTrue(expectedUpdateSetColumns.endsWith("</set>"));

        String actualSetBody = updateSetColumns.substring("<set>".length(), updateSetColumns.length() - "</set>".length());
        String expectedSetBody = expectedUpdateSetColumns.substring("<set>".length(), expectedUpdateSetColumns.length() - "</set>".length());
        Assert.assertTrue(actualSetBody.endsWith(","));
        Assert.assertTrue(expectedSetBody.endsWith(","));

        List<String> actualSetItems = new ArrayList<String>(Arrays.asList(actualSetBody.substring(0, actualSetBody.length() - 1).split(",", -1)));
        List<String> expectedSetItems = new ArrayList<String>(Arrays.asList(expectedSetBody.substring(0, expectedSetBody.length() - 1).split(",", -1)));
        Collections.sort(actualSetItems);
        Collections.sort(expectedSetItems);
        Assert.assertEquals(expectedSetItems, actualSetItems);
    }
