        String expectedWhereAllIfColumns = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";
        Pattern ifPattern = Pattern.compile("<if\\s+test=\"[^\"]*\">.*?</if>");
        Matcher expectedIfMatcher = ifPattern.matcher(expectedWhereAllIfColumns);
        Matcher actualIfMatcher = ifPattern.matcher(whereAllIfColumns);
        List<String> expectedIfColumns = new ArrayList<String>();
        while (expectedIfMatcher.find()) {
            expectedIfColumns.add(expectedIfMatcher.group());
        }
        List<String> actualIfColumns = new ArrayList<String>();
        while (actualIfMatcher.find()) {
            actualIfColumns.add(actualIfMatcher.group());
        }
        String expectedWhereAllIfColumnsSkeleton = ifPattern.matcher(expectedWhereAllIfColumns).replaceAll("");
        String actualWhereAllIfColumnsSkeleton = ifPattern.matcher(whereAllIfColumns).replaceAll("");
        Assert.assertEquals(expectedWhereAllIfColumnsSkeleton, actualWhereAllIfColumnsSkeleton);
        Collections.sort(expectedIfColumns);
        Collections.sort(actualIfColumns);
        Assert.assertEquals(expectedIfColumns, actualIfColumns);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertTrue(updateSetColumns.startsWith("<set>"));
        Assert.assertTrue(updateSetColumns.endsWith("</set>"));
        String updateSetBody = updateSetColumns.substring("<set>".length(), updateSetColumns.length() - "</set>".length());
        Assert.assertTrue(updateSetBody.endsWith(","));
        String expectedUpdateSetBody = "username = #{username},is_valid = 1,";
        String[] expectedUpdateSetArray = expectedUpdateSetBody.substring(0, expectedUpdateSetBody.length() - 1).split(",", -1);
        String[] actualUpdateSetArray = updateSetBody.substring(0, updateSetBody.length() - 1).split(",", -1);
        List<String> expectedUpdateSetColumns = new ArrayList<String>();
        for (String column : expectedUpdateSetArray) {
            expectedUpdateSetColumns.add(column);
        }
        List<String> actualUpdateSetColumns = new ArrayList<String>();
        for (String column : actualUpdateSetArray) {
            actualUpdateSetColumns.add(column);
        }
        Collections.sort(expectedUpdateSetColumns);
        Collections.sort(actualUpdateSetColumns);
        Assert.assertEquals(expectedUpdateSetColumns, actualUpdateSetColumns);
    }
