    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        Assert.assertFalse(config.isNotEmpty());

        final String tableClause = " FROM user ";
        Assert.assertTrue(sql.startsWith("SELECT "));
        final int fromIndex = sql.indexOf(tableClause);
        Assert.assertTrue(fromIndex > "SELECT ".length());
        Assert.assertEquals(-1, sql.indexOf(tableClause, fromIndex + tableClause.length()));

        final String actualColumnPart = sql.substring("SELECT ".length(), fromIndex).trim();
        final List<String> actualColumns = new ArrayList<String>();
        if (!actualColumnPart.isEmpty()) {
            String[] columns = actualColumnPart.split(",");
            for (int i = 0; i < columns.length; i++) {
                actualColumns.add(columns[i].trim());
            }
        }
        final List<String> expectedColumns = Arrays.asList("id", "user_name", "address", "state");
        final List<String> sortedExpectedColumns = new ArrayList<String>(expectedColumns);
        Collections.sort(actualColumns);
        Collections.sort(sortedExpectedColumns);
        Assert.assertEquals(sortedExpectedColumns, actualColumns);

        final String actualWhere = sql.substring(fromIndex + tableClause.length());
        Assert.assertTrue(actualWhere.startsWith("<where>"));
        Assert.assertTrue(actualWhere.endsWith("</where>"));
        final String actualWhereInner = actualWhere.substring(
                "<where>".length(),
                actualWhere.length() - "</where>".length()
        );

        final List<String> expectedIfs = Arrays.asList(
                "<if test=\"id != null\"> AND id = #{id}</if>",
                "<if test=\"userName != null\"> AND user_name = #{userName}</if>",
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
                "<if test=\"state != null\"> AND state = #{state}</if>"
        );
        final List<String> actualIfs = new ArrayList<String>();
        final Pattern ifPattern = Pattern.compile("<if test=\"[^\"]+\">[^<]*</if>");
        final Matcher ifMatcher = ifPattern.matcher(actualWhereInner);
        int position = 0;
        while (ifMatcher.find()) {
            Assert.assertEquals(position, ifMatcher.start());
            actualIfs.add(ifMatcher.group());
            position = ifMatcher.end();
        }
        Assert.assertEquals(actualWhereInner.length(), position);

        final List<String> sortedExpectedIfs = new ArrayList<String>(expectedIfs);
        Collections.sort(actualIfs);
        Collections.sort(sortedExpectedIfs);
        Assert.assertEquals(sortedExpectedIfs, actualIfs);

        final Map<String, EntityColumn> entityColumnsByProperty = new HashMap<String, EntityColumn>();
        for (EntityColumn column : entityTable.getEntityClassColumns()) {
            entityColumnsByProperty.put(column.getProperty(), column);
        }
        Assert.assertEquals(4, entityColumnsByProperty.size());
