    @Test
    public void test() {
        config.setNotEmpty(false);

        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);

        Assert.assertFalse(config.isNotEmpty());
        Assert.assertEquals("user", entityTable.getName());

        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        final List<String> expectedColumns = Arrays.asList("id", "user_name", "address", "state");
        final List<String> expectedIfs = Arrays.asList(
                "<if test=\"id != null\"> AND id = #{id}</if>",
                "<if test=\"userName != null\"> AND user_name = #{userName}</if>",
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
                "<if test=\"state != null\"> AND state = #{state}</if>"
        );

        final String columnPrefix = "SELECT ";
        final String tableSeparator = "  FROM user <where>";
        Assert.assertTrue(sql.startsWith(columnPrefix));
        final int tableSepIndex = sql.indexOf(tableSeparator);
        Assert.assertTrue(tableSepIndex > columnPrefix.length());
        Assert.assertEquals(-1, sql.indexOf(tableSeparator, tableSepIndex + tableSeparator.length()));

        final String actualColumnPart = sql.substring(columnPrefix.length(), tableSepIndex);
        Assert.assertFalse(actualColumnPart.isEmpty());
        Assert.assertEquals(actualColumnPart.trim(), actualColumnPart);
        final String[] columnArray = actualColumnPart.split(",", -1);
        final List<String> actualColumns = new ArrayList<String>();
        for (String column : columnArray) {
            Assert.assertFalse(column.isEmpty());
            Assert.assertEquals(column.trim(), column);
            actualColumns.add(column);
        }
        Assert.assertEquals(expectedColumns.size(), actualColumns.size());
        final List<String> sortedExpectedColumns = new ArrayList<String>(expectedColumns);
        final List<String> sortedActualColumns = new ArrayList<String>(actualColumns);
        Collections.sort(sortedExpectedColumns);
        Collections.sort(sortedActualColumns);
        Assert.assertEquals(sortedExpectedColumns, sortedActualColumns);

        final String whereSuffix = "</where>";
        final String actualWherePart = sql.substring(tableSepIndex + tableSeparator.length());
        Assert.assertTrue(actualWherePart.endsWith(whereSuffix));
        final String actualIfPart = actualWherePart.substring(0, actualWherePart.length() - whereSuffix.length());
        Assert.assertFalse(actualIfPart.isEmpty());
        final List<String> actualIfs = new ArrayList<String>();
        final Pattern ifPattern = Pattern.compile("<if test=\"[^\"]+\">[^<]*</if>");
        final Matcher ifMatcher = ifPattern.matcher(actualIfPart);
        int position = 0;
        while (ifMatcher.find()) {
            Assert.assertEquals(position, ifMatcher.start());
            actualIfs.add(ifMatcher.group());
            position = ifMatcher.end();
        }
        Assert.assertEquals(actualIfPart.length(), position);
        Assert.assertEquals(expectedIfs.size(), actualIfs.size());
        final List<String> sortedExpectedIfs = new ArrayList<String>(expectedIfs);
        final List<String> sortedActualIfs = new ArrayList<String>(actualIfs);
        Collections.sort(sortedExpectedIfs);
        Collections.sort(sortedActualIfs);
        Assert.assertEquals(sortedExpectedIfs, sortedActualIfs);

        final StringBuilder normalizedActualBuilder = new StringBuilder();
        normalizedActualBuilder.append(columnPrefix);
        for (int i = 0; i < sortedActualColumns.size(); i++) {
            if (i > 0) {
                normalizedActualBuilder.append(',');
            }
            normalizedActualBuilder.append(sortedActualColumns.get(i));
        }
        normalizedActualBuilder.append(tableSeparator);
        for (String ifFragment : sortedActualIfs) {
            normalizedActualBuilder.append(ifFragment);
        }
        normalizedActualBuilder.append(whereSuffix);

        final StringBuilder normalizedExpectedBuilder = new StringBuilder();
        normalizedExpectedBuilder.append(columnPrefix);
        for (int i = 0; i < sortedExpectedColumns.size(); i++) {
            if (i > 0) {
                normalizedExpectedBuilder.append(',');
            }
            normalizedExpectedBuilder.append(sortedExpectedColumns.get(i));
        }
        normalizedExpectedBuilder.append(tableSeparator);
        for (String ifFragment : sortedExpectedIfs) {
            normalizedExpectedBuilder.append(ifFragment);
        }
        normalizedExpectedBuilder.append(whereSuffix);
        Assert.assertEquals(normalizedExpectedBuilder.toString(), normalizedActualBuilder.toString());

        final Collection<EntityColumn> entityColumns = entityTable.getEntityClassColumns();
        Assert.assertNotNull(entityColumns);
        Assert.assertEquals(4, entityColumns.size());
        final Map<String, EntityColumn> entityColumnsByProperty = new HashMap<String, EntityColumn>();
        for (EntityColumn column : entityColumns) {
            Assert.assertNotNull(column);
            final String property = column.getProperty();
            Assert.assertNotNull(property);
            Assert.assertFalse(entityColumnsByProperty.containsKey(property));
            entityColumnsByProperty.put(property, column);
        }
        Assert.assertEquals(4, entityColumnsByProperty.size());
        Assert.assertEquals(
                new HashSet<String>(Arrays.asList("id", "userName", "address", "state")),
                entityColumnsByProperty.keySet()
        );

        final EntityColumn idColumn = entityColumnsByProperty.get("id");
        Assert.assertNotNull(idColumn);
        Assert.assertEquals("id", idColumn.getColumn());
        Assert.assertEquals("id", idColumn.getProperty());
        Assert.assertEquals("id = #{id}", idColumn.getColumnEqualsHolder());

        final EntityColumn userNameColumn = entityColumnsByProperty.get("userName");
        Assert.assertNotNull(userNameColumn);
        Assert.assertEquals("user_name", userNameColumn.getColumn());
        Assert.assertEquals("userName", userNameColumn.getProperty());
        Assert.assertEquals("user_name = #{userName}", userNameColumn.getColumnEqualsHolder());

        final EntityColumn addressColumn = entityColumnsByProperty.get("address");
        Assert.assertNotNull(addressColumn);
        Assert.assertEquals("address", addressColumn.getColumn());
        Assert.assertEquals("address", addressColumn.getProperty());
        Assert.assertEquals(
                "address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}",
                addressColumn.getColumnEqualsHolder()
        );

        final EntityColumn stateColumn = entityColumnsByProperty.get("state");
        Assert.assertNotNull(stateColumn);
        Assert.assertEquals("state", stateColumn.getColumn());
        Assert.assertEquals("state", stateColumn.getProperty());
        Assert.assertEquals("state = #{state}", stateColumn.getColumnEqualsHolder());

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        Assert.assertNotNull(resultMap);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals(4, resultMappings.size());

        final Map<String, ResultMapping> mappingsByProperty = new HashMap<String, ResultMapping>();
        for (ResultMapping mapping : resultMappings) {
            Assert.assertNotNull(mapping);
            final String property = mapping.getProperty();
            Assert.assertNotNull(property);
            Assert.assertFalse(mappingsByProperty.containsKey(property));
            mappingsByProperty.put(property, mapping);
        }
        Assert.assertEquals(4, mappingsByProperty.size());
        Assert.assertEquals(
                new HashSet<String>(Arrays.asList("id", "userName", "address", "state")),
                mappingsByProperty.keySet()
        );

        final ResultMapping idMapping = mappingsByProperty.get("id");
        Assert.assertNotNull(idMapping);
        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        final ResultMapping userNameMapping = mappingsByProperty.get("userName");
        Assert.assertNotNull(userNameMapping);
        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());
        Assert.assertFalse(userNameMapping.getFlags().contains(ResultFlag.ID));

        final ResultMapping addressMapping = mappingsByProperty.get("address");
        Assert.assertNotNull(addressMapping);
        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());
        Assert.assertFalse(addressMapping.getFlags().contains(ResultFlag.ID));

        final ResultMapping stateMapping = mappingsByProperty.get("state");
        Assert.assertNotNull(stateMapping);
        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
        Assert.assertFalse(stateMapping.getFlags().contains(ResultFlag.ID));
    }
